namespace CapriDesktop
{
    internal static class Program
    {
        // Set when she closed while starting twice in a row, so this start moved settings.json aside and kept her keys.
        internal static bool StartedFresh;
        internal const string StartMarker = "starting.on";
        private static string lastCrash;
        private static int lastCrashAt;

        [STAThread]
        private static int Main(string[] args)
        {
            try { Native.SetProcessDpiAwarenessContext(new IntPtr(-4)); } catch (EntryPointNotFoundException) { Native.SetProcessDPIAware(); }
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            bool smoke = args.Length == 2 && args[0] == "--smoke-test";
            string identity = WindowsIdentity.GetCurrent().User.Value;
            bool first;
            using (Mutex mutex = new Mutex(true, "Local\\Capri.Desktop." + identity + (smoke ? ".Test" : ""), out first))
            using (EventWaitHandle restore = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\Capri.Restore." + identity + (smoke ? ".Test" : "")))
            {
                if (!first) { Native.AllowSetForegroundWindow(-1); restore.Set(); return 0; }
                try
                {
                    string data = smoke ? Path.GetFullPath(args[1]) : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Capri");
                    Brain.LogPath = Path.Combine(data, "errors.txt");
                    if (!smoke)
                    {
                        Portable.Current = Portable.Detect(Application.ExecutablePath);
                        if (Portable.Current != null) { data = Portable.Current.Settings; Brain.LogPath = Path.Combine(Portable.Current.Logs, "errors.txt"); }
                        else if (Portable.Problem != null) Brain.Log("portable", -1, Portable.Problem);
                    }
                    // Whatever ends her, their own cursor comes back, and a crash goes in errors.txt.
                    AppDomain.CurrentDomain.ProcessExit += delegate { HerCursor.Off(); };
                    AppDomain.CurrentDomain.UnhandledException += delegate(object sender, UnhandledExceptionEventArgs crash) { HerCursor.Off(); Crashed(crash.ExceptionObject as Exception); };
                    if (!smoke)
                    {
                        // A crash in a timer or a click is written down and she carries on.
                        Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
                        Application.ThreadException += delegate(object sender, ThreadExceptionEventArgs crash) { Crashed(crash.Exception); };
                        StartedFresh = Starting(data);
                    }
                    using (Companion app = new Companion(data, restore, smoke))
                    {
                        if (smoke) app.StartSmokeTest(data);
                        Application.Run(app);
                        HerCursor.Off();
                        return app.TestFailed ? 1 : 0;
                    }
                }
                catch (Exception error)
                {
                    HerCursor.Off();
                    if (smoke) { Directory.CreateDirectory(args[1]); File.WriteAllText(Path.Combine(args[1], "failure.txt"), error.ToString()); return 1; }
                    Crashed(error);
                    Notice.Tell(null, "Capri could not start.\n\n" + error.Message, "Capri", true);
                    return 1;
                }
            }
        }

        // A start that never settled means she closed while starting: a crash, but also Task Manager, an antivirus, a stuck
        // shutdown or the power going off in her first 15 s. Two of those in a row move settings.json aside, the same fix as
        // deleting it, and she starts fresh with her keys kept (JustAxolotl lost theirs to one). True when that happened.
        internal static bool Starting(string data)
        {
            string marker = Path.Combine(data, StartMarker);
            string settings = Path.Combine(data, "settings.json");
            bool fresh = false;
            try
            {
                Directory.CreateDirectory(data);
                // The marker's second line counts the unfinished starts before the one that wrote it. One from before 0.7.6 has none.
                int unfinished = 0;
                if (File.Exists(marker))
                {
                    string[] lines = File.ReadAllLines(marker);
                    int earlier;
                    unfinished = 1 + (lines.Length > 1 && int.TryParse(lines[1], out earlier) && earlier > 0 ? earlier : 0);
                }
                if (unfinished >= 2 && File.Exists(settings))
                {
                    string kept = Path.Combine(data, "settings.crashed.json");
                    if (File.Exists(kept)) File.Delete(kept);
                    File.Move(settings, kept);
                    KeepKeys(kept, settings);
                    fresh = true;
                    unfinished = 0;
                    Brain.Log("startup", -1, "Capri closed while starting twice in a row, so she started with fresh settings and kept your keys. The old ones are in settings.crashed.json.");
                }
                else if (unfinished == 1) Brain.Log("startup", -1, "Capri closed while starting last time. If it happens again, she starts with fresh settings and keeps your keys.");
                File.WriteAllText(marker, DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + Environment.NewLine + unfinished);
            }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
            return fresh;
        }

        // A fresh start keeps what can't crash her: her brain and voice keys with what each one is for (model, voice, agent,
        // server), and her own keys to talk, mute, type, hide and go quiet. The rest starts like a new install. Settings that
        // can't be read keep nothing.
        private static void KeepKeys(string crashed, string settings)
        {
            Preferences old;
            try { using (FileStream stream = File.OpenRead(crashed)) old = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(stream); }
            catch (Exception) { return; }
            Preferences fresh = new Preferences { Language = Brain.SystemLanguage(System.Globalization.CultureInfo.CurrentUICulture) };
            fresh.VoiceKey = old.VoiceKey; fresh.VoiceId = old.VoiceId; fresh.VoiceModel = old.VoiceModel;
            fresh.AgentId = old.AgentId; fresh.AgentVersion = old.AgentVersion; fresh.AgentPolyglot = old.AgentPolyglot; fresh.AgentPersonality = old.AgentPersonality;
            fresh.TextKey = old.TextKey; fresh.TextModel = old.TextModel;
            fresh.NvidiaKey = old.NvidiaKey; fresh.NvidiaModel = old.NvidiaModel;
            fresh.PaidKey = old.PaidKey; fresh.PaidModel = old.PaidModel;
            fresh.ServerUrl = old.ServerUrl; fresh.ServerApi = old.ServerApi; fresh.ServerModel = old.ServerModel; fresh.ServerSpeaker = old.ServerSpeaker; fresh.ServerKey = old.ServerKey;
            fresh.AsideUrl = old.AsideUrl; fresh.AsideApi = old.AsideApi; fresh.AsideModel = old.AsideModel; fresh.AsideSpeaker = old.AsideSpeaker; fresh.AsideKey = old.AsideKey;
            fresh.CloudVoice = old.CloudVoice;
            fresh.TalkMods = old.TalkMods; fresh.TalkVk = old.TalkVk; fresh.MuteMods = old.MuteMods; fresh.MuteVk = old.MuteVk;
            fresh.TypeMods = old.TypeMods; fresh.TypeVk = old.TypeVk; fresh.HideMods = old.HideMods; fresh.HideVk = old.HideVk;
            fresh.QuietMods = old.QuietMods; fresh.QuietVk = old.QuietVk;
            try { using (FileStream stream = File.Create(settings)) new DataContractJsonSerializer(typeof(Preferences)).WriteObject(stream, fresh); }
            catch (Exception) { try { File.Delete(settings); } catch (Exception) { } }
        }

        // A crash goes in errors.txt: what it was and where in her code, so Copy error details shows it.
        internal static void Crashed(Exception error)
        {
            if (error == null) return;
            while (error.InnerException != null) error = error.InnerException;
            string what = error.GetType().Name + ": " + error.Message;
            lock (typeof(Program))
            {
                if (what == lastCrash && unchecked(Environment.TickCount - lastCrashAt) < 60000) return;
                lastCrash = what;
                lastCrashAt = Environment.TickCount;
            }
            Brain.Log("crash", -1, what);
            int shown = 0;
            foreach (string frame in (error.StackTrace ?? "").Split('\n'))
            {
                string at = frame.Trim();
                if (at.Length == 0) continue;
                Brain.Log("crash", -1, at);
                if (++shown == 4) break;
            }
        }
    }

    [DataContract]
    internal sealed class Preferences
    {
        [DataMember] public int X;
        [DataMember] public int Y;
        [DataMember] public bool HasPosition;
        [DataMember] public int Size = 240;
        public bool Motion = true;
        [DataMember] public bool OnTop = true;
        [DataMember] public long UpdateCheckedAt;
        [DataMember] public string Model;
        [DataMember] public bool Welcomed;
        // She's asked to get to know them, after setup or from Settings, so setting up a new brain doesn't ask again.
        [DataMember] public bool Met;
        [DataMember] public bool NoSitting;
        [DataMember] public bool NvidiaGlm;
        [DataMember] public string VoiceKey;
        [DataMember] public string VoiceId;
        [DataMember] public string VoiceModel;
        [DataMember] public string AgentId;
        [DataMember] public int AgentVersion;
        [DataMember] public string Mic;
        [DataMember] public string TextKey;
        [DataMember] public string TextModel;
        [DataMember] public string NvidiaKey;
        [DataMember] public string NvidiaModel;
        [DataMember] public string PaidKey;
        [DataMember] public string PaidModel;
        [DataMember] public int Tier;
        [DataMember] public bool Tiered;
        [DataMember] public bool Watch;
        [DataMember] public int GlanceGap;
        // Keep her caught up is on by default: what she saw costs a few words per chat, next to the screenshot each glance already sends.
        [DataMember] public bool CaughtUp = true;
        // Stay on my model: a stuck NVIDIA model says what went wrong instead of handing the message to another model (Zak's ask).
        [DataMember] public bool StayOnModel;
        [DataMember] public bool Quiet;
        [DataMember] public bool Silent;
        [DataMember] public bool Wander;
        [DataMember] public bool FreeVoice;
        [DataMember] public bool NoDance;
        [DataMember] public string Language;
        [DataMember] public string Nickname;
        [DataMember] public int Wordiness;
        [DataMember] public int Recall = 8;
        // Remember our chats is on by default: transcripts and memories.md stay on this PC.
        [DataMember] public bool Remembers = true;
        [DataMember] public int Volume = 100;
        [DataMember] public int Sounds = 60;
        [DataMember] public int SleepAfter = 120;
        [DataMember] public bool NoIntro;
        [DataMember] public bool NoDiscord;
        [DataMember] public int Typing;
        [DataMember] public int BubbleTime = 1;
        [DataMember] public int TalkMods = 3;
        [DataMember] public int TalkVk = 0x56;
        [DataMember] public int MuteMods = 3;
        [DataMember] public int MuteVk = 0x4E;
        [DataMember] public int TypeMods = 3;
        [DataMember] public int TypeVk = 0x54;
        [DataMember] public int HideMods = 3;
        [DataMember] public int HideVk = 0x48;
        // Her quiet key, Ctrl + Alt + P (Zenni's ask). P, since AltGr + Q types @ on German keyboards and Ctrl + Alt is AltGr.
        [DataMember] public int QuietMods = 3;
        [DataMember] public int QuietVk = 0x50;
        [DataMember] public int WanderPace = 1;
        // How often she pops in while Check in on me is on: 0 rarely, 1 sometimes (every 8 to 20 minutes, as before), 2 often.
        [DataMember] public int PopPace = 1;
        // Frames a second of her perch: 10, 15, 20, 30, 40, 50 or 60. 30 shows the art as drawn.
        [DataMember] public int PerchFps = 30;
        // Her Mainframe's size: 0 for Auto, which grows it on a screen whose desktop is bigger than its panel (Virtual Super
        // Resolution, DSR), or 100 to 200 for that percent of the screen's own scale.
        [DataMember] public int MainframeSize;
        [DataMember] public string AgentPolyglot;
        [DataMember] public string AgentPersonality;
        // Check in on me is on by default. Before 0.7.3 it was saved as PopIns, off by default, so the new name turns it on once for everyone.
        [DataMember] public bool CheckIns = true;
        [DataMember] public string VoiceStyle;
        [DataMember] public bool StartupSet;
        [DataMember] public bool QuickHands;
        [DataMember] public bool Bypass;
        // Her SECURITY window's toggles 1 to 10 as 1s and 0s, like "1111111000" for Trusted; "Hey Capri" is HeyCapri. Missing in
        // settings from before it, so Blackwall mode moves to the Blackwall preset and everyone else gets Trusted.
        [DataMember] public string Permissions;
        // Listen for "Hey Capri" is off out of the box (Lachy, 29 Oct). It's a toggle in her Security window, and the Blackwall preset turns it on.
        [DataMember] public bool HeyCapri;
        [DataMember] public bool HdVoice;
        // Free voice in games is off out of the box (Lachy, 29 Oct): her HD voice keeps talking while a game is full screen.
        // On, her free voice takes over while anything is full screen, so the game gets the graphics card back.
        [DataMember] public bool HdGameRest;
        [DataMember] public int VoicePitch;
        [DataMember] public int VoiceSpeed = 100;
        [DataMember] public int VoiceRobot;
        [DataMember] public int VoiceGlitch;
        // Her HD voice keeps its own robot and its own glitch, both Off out of the box, tuned voice included.
        // Early 0.7.4 builds saved a 10% HD glitch as HdGlitch, so the new name starts it at Off.
        [DataMember] public int HdRobot = VoiceFx.HdRobotDefault;
        [DataMember] public int HdVoiceGlitch;
        // Her voice layers (Lachy, 29 Oct): two copies of her voice under her, each with its own pitch (semitones off hers, in
        // half steps) and delay (ms). Off here and in settings from before them, which get the layers' defaults; Tune turns them on.
        [DataMember] public bool VoiceLayers;
        [DataMember] public double LayerPitch1 = VoiceFx.Layering.HigherPitch;
        [DataMember] public int LayerDelay1 = VoiceFx.Layering.Behind;
        [DataMember] public double LayerPitch2 = VoiceFx.Layering.LowerPitch;
        [DataMember] public int LayerDelay2 = VoiceFx.Layering.Behind;
        // Their own voice model under CUSTOM LOCAL, or Fish Audio or OpenAI under CLOUD VOICE. Its key is sealed like her other
        // keys. Its robot and glitch are its own and start at Off. ServerApi is "fish" for Fish Audio's API, and null for OpenAI's.
        [DataMember] public bool ServerVoice;
        [DataMember] public string ServerUrl;
        [DataMember] public string ServerApi;
        [DataMember] public string ServerModel;
        [DataMember] public string ServerSpeaker;
        [DataMember] public string ServerKey;
        [DataMember] public int ServerRobot;
        [DataMember] public int ServerGlitch;
        // The other kind they set up, local or cloud, kept aside while the one above is in use, so each row keeps its own.
        [DataMember] public string AsideUrl;
        [DataMember] public string AsideApi;
        [DataMember] public string AsideModel;
        [DataMember] public string AsideSpeaker;
        [DataMember] public string AsideKey;
        // The service CLOUD VOICE last used: ElevenLabs, Fish Audio or OpenAI. Its menu shows it while another row is in use.
        [DataMember] public string CloudVoice;
        // Her mini player shows while music plays. It's on by default, so it's saved as switched off.
        [DataMember] public bool NoPlayer;
        // Where they dragged the mini player: its plate's bottom-left on screen.
        [DataMember] public int PlayerX;
        [DataMember] public int PlayerY;
        [DataMember] public bool HasPlayerSpot;
        // Set once she has her tuned voice, or kept theirs because they'd already moved a voice slider.
        [DataMember] public bool VoiceTuned;

        // A new install: she starts in the PC's own language when she speaks it, and with her tuned voice.
        internal static Preferences Fresh()
        {
            Preferences fresh = new Preferences { Language = Brain.SystemLanguage(System.Globalization.CultureInfo.CurrentUICulture) };
            fresh.Tune();
            return fresh;
        }

        // Her voice as Lachy tuned it (30 Oct: "free voice settings default"): 80% volume, pitch +3, 1.2x, robot and glitch left
        // Off, and her voice layers on at their defaults. Pitch, speed, volume and layers go for every voice.
        internal void Tune()
        {
            Volume = 80;
            VoicePitch = 3;
            VoiceSpeed = 120;
            VoiceLayers = true;
            LayerPitch1 = VoiceFx.Layering.HigherPitch;
            LayerDelay1 = VoiceFx.Layering.Behind;
            LayerPitch2 = VoiceFx.Layering.LowerPitch;
            LayerDelay2 = VoiceFx.Layering.Behind;
            VoiceTuned = true;
        }

        // Settings from before her tuned voice get it once if every voice slider is still where it started (Layer 1 started at
        // +1.5); anyone who moved one keeps theirs.
        internal void TuneOnce()
        {
            if (VoiceTuned) return;
            bool untouched = Volume == 100 && VoicePitch == 0 && VoiceSpeed == 100 && VoiceRobot == 0 && VoiceGlitch == 0 && HdRobot == 0 && HdVoiceGlitch == 0 && !VoiceLayers
                && (LayerPitch1 == 1.5 || LayerPitch1 == VoiceFx.Layering.HigherPitch) && LayerDelay1 == VoiceFx.Layering.Behind && LayerPitch2 == VoiceFx.Layering.LowerPitch && LayerDelay2 == VoiceFx.Layering.Behind;
            if (untouched) Tune();
            VoiceTuned = true;
        }

        [OnDeserializing]
        private void Defaults(StreamingContext context)
        {
            VoiceSpeed = 100;
            HdRobot = VoiceFx.HdRobotDefault;
            LayerPitch1 = VoiceFx.Layering.HigherPitch;
            LayerDelay1 = VoiceFx.Layering.Behind;
            LayerPitch2 = VoiceFx.Layering.LowerPitch;
            LayerDelay2 = VoiceFx.Layering.Behind;
            Size = 240;
            Motion = true;
            OnTop = true;
            Recall = 8;
            Remembers = true;
            Volume = 100;
            Sounds = 60;
            SleepAfter = 120;
            BubbleTime = 1;
            TalkMods = 3;
            TalkVk = 0x56;
            MuteMods = 3;
            MuteVk = 0x4E;
            TypeMods = 3;
            TypeVk = 0x54;
            HideMods = 3;
            HideVk = 0x48;
            QuietMods = 3;
            QuietVk = 0x50;
            WanderPace = 1;
            PopPace = 1;
            PerchFps = 30;
            MainframeSize = 0;
            CheckIns = true;
            CaughtUp = true;
        }
    }

    [DataContract]
    internal sealed class Release
    {
        [DataMember(Name = "tag_name")] public string Tag;
        [DataMember(Name = "draft")] public bool Draft;
        [DataMember(Name = "prerelease")] public bool Prerelease;
        [DataMember(Name = "assets")] public ReleaseAsset[] Assets;
    }

    [DataContract]
    internal sealed class ReleaseAsset
    {
        [DataMember(Name = "id")] public long Id;
        [DataMember(Name = "name")] public string Name;
        [DataMember(Name = "browser_download_url")] public string Url;
        [DataMember(Name = "size")] public long Size;
    }

    internal sealed class UpdateFile
    {
        internal string Version;
        internal string Path;
        internal string Hash;
        internal long Size;
    }

    internal sealed class Updater
    {
        private readonly string folder;
        private readonly string app;
        private readonly bool local;
        internal Func<Release> Latest = Companion.FetchLatestRelease;
        internal Func<string, string> Signer = SignedBy;
        internal Action<ProcessStartInfo> Run = delegate(ProcessStartInfo command)
        {
            using (Process process = Process.Start(command)) if (process == null) throw new IOException("The update installer did not start.");
        };

        internal Updater(string data, string executable, bool smoke)
        {
            folder = Path.GetFullPath(Path.Combine(data, "updates"));
            app = executable;
            local = smoke;
            if (smoke)
            {
                Latest = delegate { throw new Exception("The update check needs a fake release."); };
                Run = delegate { throw new Exception("The update installer needs a fake process start."); };
            }
        }

        internal static ReleaseAsset Installer(Release release)
        {
            ReleaseAsset first = null;
            ReleaseAsset plain = null;
            if (release == null || release.Assets == null) return null;
            foreach (ReleaseAsset asset in release.Assets)
            {
                if (asset == null || asset.Name == null || !asset.Name.StartsWith("Capri-Setup", StringComparison.OrdinalIgnoreCase) || !asset.Name.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) || asset.Name.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0) continue;
                if (string.Equals(asset.Name, "Capri-Setup-" + (release.Tag ?? "").TrimStart('v', 'V') + ".exe", StringComparison.OrdinalIgnoreCase)) return asset;
                if (string.Equals(asset.Name, "Capri-Setup.exe", StringComparison.OrdinalIgnoreCase)) plain = asset;
                if (first == null) first = asset;
            }
            return plain ?? first;
        }

        internal UpdateFile Download(Release release)
        {
            Version version;
            if (release == null || release.Draft || release.Prerelease || !Companion.ReleaseVersion(release.Tag, out version)) throw new BrainException("This release can't be installed.");
            ReleaseAsset asset = Installer(release);
            if (asset == null) throw new BrainException("This release has no Capri installer.");
            if (asset.Size <= 0 || asset.Size > 512L * 1024 * 1024) throw new BrainException("The update size is invalid.");
            Address(asset.Url);
            ReleaseAsset sums = null;
            foreach (ReleaseAsset entry in release.Assets)
                if (entry != null && string.Equals(entry.Name, "SHA256SUMS.txt", StringComparison.OrdinalIgnoreCase))
                {
                    if (sums != null) throw new BrainException("This release has more than one checksum file.");
                    sums = entry;
                }
            string hash = null;
            if (sums != null)
            {
                using (MemoryStream memory = new MemoryStream())
                {
                    Copy(sums.Url, memory, 1024 * 1024, -1);
                    memory.Position = 0;
                    using (StreamReader reader = new StreamReader(memory)) hash = Checksum(reader.ReadToEnd(), asset.Name);
                }
            }
            UpdateFile update = new UpdateFile { Version = version.Revision == 0 ? version.ToString(3) : version.ToString(4), Hash = hash, Size = asset.Size };
            update.Path = Path.Combine(folder, "Capri-Setup-" + update.Version + "-" + asset.Id + ".exe");
            Directory.CreateDirectory(folder);
            string partial = update.Path + ".partial";
            if (File.Exists(partial)) File.Delete(partial);
            if (File.Exists(update.Path))
            {
                Verify(update.Path, update, true);
                return update;
            }
            try
            {
                using (FileStream target = new FileStream(partial, FileMode.CreateNew, FileAccess.Write, FileShare.None)) Copy(asset.Url, target, asset.Size, asset.Size);
                Verify(partial, update);
                File.Move(partial, update.Path);
                return update;
            }
            finally { if (File.Exists(partial)) File.Delete(partial); }
        }

        internal static string Checksum(string text, string name)
        {
            string found = null;
            foreach (string line in text.Split('\n'))
            {
                Match match = Regex.Match(line.TrimEnd('\r'), @"^([a-fA-F0-9]{64})[ \t]+\*?(.+)$");
                if (!match.Success || match.Groups[2].Value != name) continue;
                if (found != null) throw new BrainException("The installer checksum is listed twice.");
                found = match.Groups[1].Value;
            }
            if (found == null) throw new BrainException("The installer checksum is missing.");
            return found;
        }

        private Uri Address(string address)
        {
            Uri uri;
            if (!Uri.TryCreate(address, UriKind.Absolute, out uri) || uri.UserInfo.Length != 0 || uri.Fragment.Length != 0) throw new BrainException("The update download address is invalid.");
            if (local && uri.IsLoopback && uri.Scheme == Uri.UriSchemeHttp) return uri;
            if (uri.Scheme != Uri.UriSchemeHttps || !uri.IsDefaultPort || uri.Host != "github.com" || !uri.AbsolutePath.StartsWith("/lachydotmcg/capri-desktop/releases/download/", StringComparison.Ordinal)) throw new BrainException("The update download address is invalid.");
            return uri;
        }

        private void Copy(string address, Stream target, long limit, long expected)
        {
            Uri uri = Address(address);
            ServicePointManager.SecurityProtocol |= (SecurityProtocolType)3072;
            Stopwatch elapsed = Stopwatch.StartNew();
            for (int redirect = 0; redirect < 6; redirect++)
            {
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(uri);
                request.UserAgent = "Capri-Desktop";
                request.Timeout = 15000;
                request.ReadWriteTimeout = 15000;
                request.AllowAutoRedirect = false;
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                {
                    int status = (int)response.StatusCode;
                    if (status == 301 || status == 302 || status == 303 || status == 307 || status == 308)
                    {
                        Uri next;
                        if (!Uri.TryCreate(uri, response.Headers["Location"], out next) || next.UserInfo.Length != 0 || (next.Scheme != Uri.UriSchemeHttps && !(local && next.IsLoopback && next.Scheme == Uri.UriSchemeHttp))) throw new BrainException("The update download moved to an invalid address.");
                        uri = next;
                        continue;
                    }
                    if (status != 200 || response.ContentLength > limit || (expected >= 0 && response.ContentLength >= 0 && response.ContentLength != expected)) throw new BrainException("The update download is incomplete.");
                    using (Stream source = response.GetResponseStream())
                    {
                        byte[] buffer = new byte[65536];
                        long total = 0;
                        int count;
                        while ((count = source.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            total += count;
                            if (total > limit || elapsed.Elapsed.TotalMinutes > 10) throw new BrainException("The update download didn't finish.");
                            target.Write(buffer, 0, count);
                        }
                        if ((expected >= 0 && total != expected) || (response.ContentLength >= 0 && total != response.ContentLength)) throw new BrainException("The update download is incomplete.");
                    }
                    return;
                }
            }
            throw new BrainException("The update download moved too many times.");
        }

        private void Verify(string path, UpdateFile update, bool cached = false)
        {
            string problem = null;
            using (FileStream file = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                if (file.Length != update.Size) problem = "The update download is incomplete.";
                else if (update.Hash != null)
                    using (SHA256 sha = SHA256.Create())
                        if (!string.Equals(BitConverter.ToString(sha.ComputeHash(file)).Replace("-", ""), update.Hash, StringComparison.OrdinalIgnoreCase)) problem = "The update checksum doesn't match. It won't run.";
                if (problem == null)
                {
                    string own = Signer(app);
                    if (own != null && !string.Equals(own, Signer(path), StringComparison.Ordinal)) throw new BrainException("The update signer doesn't match Capri. It won't run.");
                    if (update.Hash == null && own == null) throw new BrainException("This update has no checksum or matching signature. It won't run.");
                }
            }
            if (problem != null) { if (cached) File.Delete(path); throw new BrainException(problem); }
        }

        internal void Install(UpdateFile update, int parent, long started)
        {
            if (update == null || !string.Equals(Path.GetDirectoryName(Path.GetFullPath(update.Path)), folder, StringComparison.OrdinalIgnoreCase) || !update.Path.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) || parent <= 0 || started <= 0) throw new BrainException("The update isn't ready to install.");
            using (FileStream file = new FileStream(update.Path, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                Verify(update.Path, update);
                Run(new ProcessStartInfo(update.Path, "--update " + parent.ToString(System.Globalization.CultureInfo.InvariantCulture) + " " + started.ToString(System.Globalization.CultureInfo.InvariantCulture)) { UseShellExecute = false, CreateNoWindow = true, WorkingDirectory = folder });
            }
        }

        internal static string SignedBy(string path)
        {
            TrustFile file = new TrustFile { Size = (uint)Marshal.SizeOf(typeof(TrustFile)), Path = path };
            IntPtr pointer = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(TrustFile)));
            Marshal.StructureToPtr(file, pointer, false);
            TrustData data = new TrustData { Size = (uint)Marshal.SizeOf(typeof(TrustData)), Ui = 2, Choice = 1, File = pointer, State = 1, Flags = 128 };
            Guid action = new Guid("00AAC56B-CD44-11D0-8CC2-00C04FC295EE");
            try
            {
                int result = WinVerifyTrust(new IntPtr(-1), ref action, ref data);
                if (result == unchecked((int)0x800B0100)) return null;
                if (result != 0) throw new BrainException("Windows couldn't verify the update signature. It won't run.");
                X509Certificate certificate = X509Certificate.CreateFromSignedFile(path);
                try { using (SHA256 sha = SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(certificate.GetRawCertData())); }
                finally { certificate.Reset(); }
            }
            finally
            {
                data.State = 2;
                WinVerifyTrust(new IntPtr(-1), ref action, ref data);
                Marshal.DestroyStructure(pointer, typeof(TrustFile));
                Marshal.FreeHGlobal(pointer);
            }
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct TrustFile
        {
            internal uint Size;
            [MarshalAs(UnmanagedType.LPWStr)] internal string Path;
            internal IntPtr File;
            internal IntPtr Subject;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct TrustData
        {
            internal uint Size;
            internal IntPtr Policy;
            internal IntPtr Sip;
            internal uint Ui;
            internal uint Revocation;
            internal uint Choice;
            internal IntPtr File;
            internal uint State;
            internal IntPtr StateData;
            internal IntPtr Url;
            internal uint Flags;
            internal uint Context;
            internal IntPtr Signatures;
        }

        [DllImport("wintrust.dll", ExactSpelling = true)] private static extern int WinVerifyTrust(IntPtr window, ref Guid action, ref TrustData data);
    }

    internal sealed class Clip
    {
        // Art that only some moments need loads off her thread when she might need it and is let go after this long undrawn:
        // every facing-left set, and the clips made lazy (her perch talking). The rest loads with her, as it always has.
        internal const int RestAfter = 90000;
        private static readonly System.Collections.Generic.List<Clip> all = new System.Collections.Generic.List<Clip>();
        private readonly string name;
        private readonly bool lazy;
        private readonly bool flippable;
        private readonly Clip source;
        private readonly object gate = new object();
        private Bitmap strip;
        // her artist's facing-left frames, for the clips that have them (her perches): her red arm and leg swap sides, so a
        // mirror of Strip isn't her. They're stored mirrored back onto Strip's cells and drawn mirrored like the rest.
        private Bitmap flipped;
        private bool fetching;
        private int stripUsed, flippedUsed;
        internal readonly int Count;
        internal readonly double Fps;
        internal readonly float Height;
        // How far a cell's middle sits from the middle of her square, as a share of her size. Narrow cells cut to the art need it.
        internal readonly float ShiftX, ShiftY;

        internal Clip(string name, int count, double fps, float height, float shiftX = 0, float shiftY = 0, bool lazy = false)
        {
            this.name = name;
            this.lazy = lazy;
            Count = count;
            Fps = fps;
            Height = height;
            ShiftX = shiftX;
            ShiftY = shiftY;
            if (!Companion.HasArt(Resource(false))) throw new FileNotFoundException("Capri's " + name + " animation is missing. Rebuild with assets/sprites.");
            flippable = Companion.HasArt(Resource(true));
            if (!lazy) strip = Companion.LoadArt(Resource(false));
            lock (all) all.Add(this);
        }

        // Another clip's art under a new name, like her dance: her idle with a nod on top.
        internal Clip(Clip art)
        {
            source = art;
            Count = art.Count;
            Fps = art.Fps;
            Height = art.Height;
            ShiftX = art.ShiftX;
            ShiftY = art.ShiftY;
        }

        private string Resource(bool left) { return "Capri.Sprite." + name + (left ? "_flipped" : "") + ".png"; }

        // Her facing-right art, or her only art. A lazy clip that isn't in yet loads on the spot.
        internal Bitmap Strip
        {
            get
            {
                if (source != null) return source.Strip;
                stripUsed = Environment.TickCount;
                Bitmap art = strip;
                if (art != null) return art;
                lock (gate)
                {
                    if (strip == null) strip = Companion.LoadArt(Resource(false));
                    return strip;
                }
            }
        }

        // Her facing-left art, or null for clips without any and while it loads, which asking for it starts. Until it's in
        // she's drawn as a mirror of Strip.
        internal Bitmap Flipped
        {
            get
            {
                if (source != null) return source.Flipped;
                if (!flippable) return null;
                flippedUsed = Environment.TickCount;
                Bitmap art = flipped;
                if (art == null) Warm(true);
                return art;
            }
        }

        // The facing-left art straight away, loading it here if it isn't in. For her smoke test.
        internal Bitmap FlippedNow
        {
            get
            {
                if (source != null) return source.FlippedNow;
                if (!flippable) return null;
                flippedUsed = Environment.TickCount;
                lock (gate)
                {
                    if (flipped == null) flipped = Companion.LoadArt(Resource(true));
                    return flipped;
                }
            }
        }

        internal bool HasFlipped { get { return source != null ? source.HasFlipped : flippable; } }

        // Loads the art for that way round here and now, if it isn't in, for when she needs it this frame.
        internal void Load(bool left)
        {
            if (source != null) { source.Load(left); return; }
            bool wantLeft = left && flippable;
            if (wantLeft) flippedUsed = Environment.TickCount; else stripUsed = Environment.TickCount;
            lock (gate)
            {
                if (wantLeft && flipped == null) flipped = Companion.LoadArt(Resource(true));
                else if (!wantLeft && strip == null) strip = Companion.LoadArt(Resource(false));
            }
        }

        // Whether the art for that way round is in, so she can show it without waiting: facing left, that's her artist's
        // flipped set when the clip has one.
        internal bool Ready(bool left)
        {
            if (source != null) return source.Ready(left);
            return left && flippable ? flipped != null : strip != null;
        }

        // Starts loading the art for that way round off her thread, and counts as using it, so it stays in while she asks.
        internal void Warm(bool left)
        {
            if (source != null) { source.Warm(left); return; }
            bool wantLeft = left && flippable;
            if (wantLeft) flippedUsed = Environment.TickCount; else stripUsed = Environment.TickCount;
            lock (gate)
            {
                if (fetching || (wantLeft ? flipped != null : strip != null)) return;
                fetching = true;
            }
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                Bitmap art = null;
                // A load that fails, out of memory say, leaves her drawn as she was, and the next ask tries again.
                try { art = Companion.LoadArt(Resource(wantLeft)); }
                catch (Exception) { }
                lock (gate)
                {
                    fetching = false;
                    if (art == null) return;
                    if (wantLeft && flipped == null) flipped = art;
                    else if (!wantLeft && strip == null) strip = art;
                    else art.Dispose();
                }
            });
        }

        // Lets go of art undrawn for RestAfter: lazy clips' own, and every facing-left set. Called on her thread, between frames.
        internal static void RestAll(int now)
        {
            Clip[] clips;
            lock (all) clips = all.ToArray();
            foreach (Clip clip in clips) clip.Rest(now);
        }

        private void Rest(int now)
        {
            lock (gate)
            {
                if (fetching) return;
                if (lazy && strip != null && unchecked(now - stripUsed) > RestAfter) { strip.Dispose(); strip = null; }
                if (flipped != null && unchecked(now - flippedUsed) > RestAfter) { flipped.Dispose(); flipped = null; }
            }
        }

        // How much of her art is in memory, in bytes, for her smoke test.
        internal static long Loaded()
        {
            Clip[] clips;
            lock (all) clips = all.ToArray();
            long bytes = 0;
            foreach (Clip clip in clips)
                lock (clip.gate)
                    foreach (Bitmap art in new[] { clip.strip, clip.flipped })
                        if (art != null) bytes += 4L * art.Width * art.Height;
            return bytes;
        }

        internal static void DisposeAll()
        {
            Clip[] clips;
            lock (all) { clips = all.ToArray(); all.Clear(); }
            foreach (Clip clip in clips)
                lock (clip.gate)
                {
                    if (clip.strip != null) clip.strip.Dispose();
                    if (clip.flipped != null) clip.flipped.Dispose();
                    clip.strip = clip.flipped = null;
                }
        }
    }

