        internal Companion(string data, EventWaitHandle signal, bool smoke)
        {
            groove = new Groove(delegate { return clock.Elapsed.TotalSeconds; });
            dance = new Clip(idle);
            Takeover.Face = LoadArt("Capri.Sprite.face.png");
            testing = smoke;
            instant = smoke;
            speaker = new Speaker(smoke);
            effects = new Speaker(smoke) { Plain = true };
            typist = new Speaker(smoke) { Plain = true };
            restore = signal;
            settingsPath = Path.Combine(data, "settings.json");
            HerCursor.Marker = Path.Combine(data, "her-cursor.on");
            // Smoke tests never touch the real Windows cursor.
            if (smoke) HerCursor.Apply = delegate(bool on) { cursorSwaps.Add(on); };
            HerCursor.Recover();
            Computer.Track = herPointer.MoveTo;
            Computer.Tapped = delegate { Post(herPointer.Tap); };
            Computer.Lending = Lend;
            taskPanel.Moved += delegate { if (onPanel) { HoldPanel(); Location = anchor; } };
            updater = new Updater(data, Application.ExecutablePath, smoke);
            updateExit = delegate { quitting = true; Close(); };
            startMarker = smoke ? null : Path.Combine(data, Program.StartMarker);
            Portable usb = Portable.Current;
            string voiceData = usb == null ? data : usb.Voices;
            Brain.LogPath = Path.Combine(usb == null ? data : usb.Logs, "errors.txt");
            Brain.MemoryPath = Path.Combine(usb == null ? data : usb.Memory, "me.md");
            Brain.MemoriesPath = Path.Combine(usb == null ? data : usb.Memory, "memories.md");
            Brain.TranscriptPath = Path.Combine(usb == null ? data : usb.Conversations, "transcripts");
            engine = new Engine(data);
            kokoro = new LocalVoice(voiceData);
            qwen = new QwenVoice(voiceData);
            ModelFile.Engine = LocalVoice.Folder(voiceData);
            ModelFile.Shelf = Path.Combine(Path.Combine(voiceData, "voice"), "models");
            parakeet = new LocalEars(voiceData);
            heyCapri = new WakeWord(voiceData);
            presence = new Presence(Assembly.GetExecutingAssembly().GetName().Version.ToString(3));
            preferences = smoke ? new Preferences() : LoadPreferences();
            // SECURITY: their toggles, with "Hey Capri" kept in its own setting for her wake word.
            Migrate(preferences);
            Security.Load(preferences.Permissions);
            Security.HeyOn = delegate { return preferences.HeyCapri; };
            Security.SetHey = SetHeyCapri;
            Security.Changed = SecurityChanged;
            ears.Chosen = preferences.Mic;
            kokoro.Style = LocalVoice.Find(preferences.VoiceStyle);
            Brain.Language = Brain.LanguageCode(preferences.Language) == "en" ? null : preferences.Language;
            PointEars();
            Brain.Nickname = Brain.Nick(preferences.Nickname).Length == 0 ? null : Brain.Nick(preferences.Nickname);
            Brain.Wordiness = Math.Max(0, Math.Min(2, preferences.Wordiness));
            Brain.Recall = preferences.Recall == 16 || preferences.Recall == 32 ? preferences.Recall : 8;
            Brain.Keeping = preferences.Remembers;
            Brain.Digging = !smoke;
            if (!smoke) Brain.Keeper = brain;
            if (!smoke) brain.Load(Path.Combine(usb == null ? data : usb.Conversations, "chat.json"));
            Voice.Loudness = Math.Max(0, Math.Min(150, preferences.Volume));
            VoiceFx.Pitch = Math.Max(-VoiceFx.MostPitch, Math.Min(VoiceFx.MostPitch, preferences.VoicePitch));
            VoiceFx.Speed = Math.Max(VoiceFx.Slowest, Math.Min(VoiceFx.Fastest, preferences.VoiceSpeed));
            VoiceFx.Robot = Math.Max(0, Math.Min(100, preferences.VoiceRobot));
            VoiceFx.HdRobot = Math.Max(0, Math.Min(100, preferences.HdRobot));
            VoiceFx.Glitch = Math.Max(0, Math.Min(100, preferences.VoiceGlitch));
            VoiceFx.HdGlitch = Math.Max(0, Math.Min(100, preferences.HdVoiceGlitch));
            VoiceFx.ServerRobot = Math.Max(0, Math.Min(100, preferences.ServerRobot));
            VoiceFx.ServerGlitch = Math.Max(0, Math.Min(100, preferences.ServerGlitch));
            VoiceFx.Layers = LayersOf(preferences);
            LoadServer();
            Sfx.Level = Math.Max(0, Math.Min(100, preferences.Sounds));
            Sfx.Out = delegate(short[] sound) { Post(delegate { Effect(sound); }); };
            Sfx.TypeOut = delegate(short[] sound) { if (IsDisposed) return; try { typist.Open(Sfx.Rate); typist.Play(sound); } catch (Exception) { } };
            Sfx.Untyped = delegate { try { typist.Clear(); } catch (Exception) { } };
            preferences.WanderPace = Math.Max(0, Math.Min(3, preferences.WanderPace));
            preferences.PopPace = Math.Max(0, Math.Min(2, preferences.PopPace));
            clip = idle;
