            moves.DropDownItems.Add(new ToolStripMenuItem("Bring to this screen", null, delegate { RestoreAtCursor(); }));
            screenItem = new ToolStripMenuItem("Go to the next screen", null, delegate { MoveSelf("other_screen", null); });
            moves.DropDownItems.Add(screenItem);
            menu.Items.Add(moves);
            menu.Opening += delegate { sitHereItem.Text = seat != null && seat.Free ? "Stand up" : "Sit here"; hangHereItem.Text = hanging ? "Let go" : "Hang here"; lieItem.Text = lying ? "Sit up" : "Lie down"; lieItem.Enabled = lying || (clip == perch && LieWay() != null); sleepItem.Text = napAsked || Asleep ? "Wake up" : "Go to sleep"; danceNowItem.Checked = danceAsked; screenItem.Visible = Screen.AllScreens.Length > 1; };
            clickDelay = new System.Windows.Forms.Timer();
            clickDelay.Interval = Math.Max(100, SystemInformation.DoubleClickTime);
            clickDelay.Tick += delegate { OnClickDelay(); };
            helpItem = new ToolStripMenuItem("Help");
            helpItem.DropDownItems.Add(new ToolStripMenuItem("Help page", null, delegate { OpenHelp(); }));
            helpItem.DropDownItems.Add(new ToolStripMenuItem("Join the Discord", null, delegate { OpenPage(DiscordPage); }));
            helpItem.DropDownItems.Add(new ToolStripMenuItem("Copy error details", null, delegate { CopyErrors(); }));
            checkItem = new ToolStripMenuItem("Check for updates", null, delegate { CheckForUpdates(true); });
            helpItem.DropDownItems.Add(checkItem);
            updateItem = new ToolStripMenuItem("Restart to update", null, delegate { InstallUpdate(); });
            menu.Items.Add(helpItem);
            foreach (ToolStripMenuItem parent in new[] { sizes, moves, helpItem })
            {
                ToolStripDropDownMenu drop = (ToolStripDropDownMenu)parent.DropDown;
                drop.Renderer = menu.Renderer;
                drop.ForeColor = menu.ForeColor;
                drop.BackColor = menu.BackColor;
                drop.Font = menu.Font;
                drop.ShowImageMargin = false;
                drop.ShowCheckMargin = parent != helpItem;
            }
            menu.Items.Add(new ToolStripSeparator());
            menu.Items.Add(new ToolStripMenuItem("Quit Capri", null, delegate { Quit(); }));
            playerMenu = new ContextMenuStrip();
            playerMenu.Renderer = menu.Renderer;
            playerMenu.ForeColor = menu.ForeColor;
            playerMenu.BackColor = menu.BackColor;
            playerMenu.Font = menu.Font;
            playerMenu.ShowImageMargin = false;
            playerOpenItem = new ToolStripMenuItem("Open the player", null, delegate { Tune tune = player.Tune; ThreadPool.QueueUserWorkItem(delegate { try { Tunes.Open(tune); } catch (Exception) { } }); });
            playerMenu.Items.Add(playerOpenItem);
            playerMenu.Items.Add(new ToolStripMenuItem("Hide for now", null, delegate { playerClosed = true; HidePlayer(); }));
            playerMenu.Items.Add(new ToolStripMenuItem("Turn off mini player", null, delegate { TogglePlayer(); }));
            player.Command += PlayerCommand;
            player.Moved += SavePlayerSpot;
            tray = new NotifyIcon();
            using (Stream icon = Assembly.GetExecutingAssembly().GetManifestResourceStream("Capri.Chip.ico"))
            {
                tray.Icon = icon != null ? new Icon(icon) : Icon.ExtractAssociatedIcon(Application.ExecutablePath);
            }
            tray.Text = "Capri · Double-click to restore";
            tray.ContextMenuStrip = menu;
            tray.DoubleClick += delegate { RestoreAtCursor(); };
            tray.BalloonTipClicked += delegate { BalloonClicked(); };
            tray.Visible = !testing;
            mainframe = new Mainframe(this, tray.Icon, Assembly.GetExecutingAssembly().GetName().Version.ToString(3));
            voice.Key = Voice.Unprotect(preferences.VoiceKey);
            Hands.Look = LookAt;
            Hands.Work = RunJob;
            brain.Act = DoTool;
            Hands.Resume = ResumeJob;
            Hands.Rename = CallThem;
            Hands.Nap = NapTool;
            Hands.MoveSelf = MoveTool;
            Hands.Animate = AnimateTool;
            Hands.Hush = Computer.Mask;
            Computer.Grab = HandsGrab;
            Computer.Halted = brain.StopDriving;
            string textKey = Voice.Unprotect(preferences.TextKey);
            if (!preferences.NvidiaGlm)
            {
                if (textKey != null && Cloud.KindOf(textKey) == "nvidia") preferences.TextModel = Brain.NvidiaDefault;
                preferences.NvidiaGlm = true;
                if (!testing) SavePreferences();
            }
            SplitKeys();
            brain.Remote = TierCloud();
            ShowTiers();
            voice.VoiceId = string.IsNullOrEmpty(preferences.VoiceId) ? null : preferences.VoiceId;
            voice.Model = string.IsNullOrEmpty(preferences.VoiceModel) ? null : preferences.VoiceModel;
            ShowVoice();
            mainframe.ShowMic(MicName(preferences.Mic));
            pill.Typing += OpenTyper;
            pill.Voice += ToggleChat;
            pill.Mute += ToggleMic;
            ears.Heard += Listen;
            ears.Level += delegate(double value) { Post(delegate { HeardLevel(value); }); };
            heyCapri.Heard += delegate { Post(HeardHeyCapri); };
            HeyCapriChanged += WakeChanged;
            getWakeVoice = delegate { SetUpFreeVoice(true); };
            getWakePack = FetchWake;
            box.Dismissed += delegate { if (box.Leaving < 0) box.Leaving = clock.Elapsed.TotalSeconds; };
            typer.Submitted += Hear;
            typer.VisibleChanged += delegate { if (!typer.Visible && replyDone >= 0) replyDone = clock.Elapsed.TotalSeconds; };
            frames = new System.Windows.Forms.Timer();
            frames.Interval = 33;
            frames.Tick += delegate { Tick(); };
            chatTail = new System.Windows.Forms.Timer();
            chatTail.Interval = 120;
            chatTail.Tick += delegate { ChatTail(); };
            signals = new System.Windows.Forms.Timer();
            signals.Interval = 250;
            signals.Tick += delegate
            {
                if (restore.WaitOne(0)) { RestoreAtCursor(); mainframe.Restore(); }
                if (startMarker != null && clock.Elapsed.TotalSeconds >= 15) Settled();
                if (!testing) CheckIdle(Native.IdleMilliseconds());
                if (!testing) CheckGlance(clock.Elapsed.TotalSeconds, Native.IdleMilliseconds());
                if (!testing) CheckWander(clock.Elapsed.TotalSeconds, Native.IdleMilliseconds());
                if (!testing) CheckMusic(clock.Elapsed.TotalSeconds);
                if (!testing) CheckPlayer(clock.Elapsed.TotalSeconds);
                if (!testing) CheckHome(clock.Elapsed.TotalSeconds);
                if (!testing) CheckLag(clock.Elapsed.TotalSeconds);
                if (!testing) CheckLie(clock.Elapsed.TotalSeconds);
                if (!testing) Clip.RestAll(Environment.TickCount);
                if (!testing) CheckPopIn(clock.Elapsed.TotalSeconds, Native.IdleMilliseconds());
                if (!testing) CheckNudge(clock.Elapsed.TotalSeconds, Native.IdleMilliseconds());
                if (!testing) CheckHoliday(DateTime.Now, Native.IdleMilliseconds());
                if (!testing) presence.Show(preferences.NoDiscord ? null : Doing);
                if (!testing) CheckHd(clock.Elapsed.TotalSeconds);
                StayOnTop();
                CheckSeat(clock.Elapsed.TotalSeconds);
                CheckChat(clock.Elapsed.TotalSeconds);
                if (!testing) CheckHearing(clock.Elapsed.TotalSeconds);
                CheckEars(clock.Elapsed.TotalSeconds);
                CheckWake(clock.Elapsed.TotalSeconds);
                CheckSlow(clock.Elapsed.TotalSeconds);
                UpdatePill(clock.Elapsed.TotalSeconds);
                if (!testing && UpdateDue(preferences.UpdateCheckedAt, DateTime.UtcNow.Ticks, clock.Elapsed.TotalSeconds, updateStarted)) CheckForUpdates(false);
            };
            signals.Start();
            if (usb != null)
            {
                drive = new DriveGuard(usb.Here, 2000);
                drive.Gone += delegate { Post(DriveGone); };
                drive.Back += delegate { Post(DriveBack); };
                drive.Start();
            }
            Size = CanvasSize(preferences.Size);
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            anchor = preferences.HasPosition ? new Point(preferences.X, preferences.Y) : new Point(work.Right - Width - 28, work.Bottom - Height - 12);
            anchor = KeepOnScreen(anchor);
            Location = anchor;
            Microsoft.Win32.SystemEvents.DisplaySettingsChanged += DisplaysChanged;
        }

        protected override bool ShowWithoutActivation { get { return true; } }

        protected override CreateParams CreateParams
        {
            get
            {
                CreateParams value = base.CreateParams;
                value.ExStyle |= 0x00080000 | 0x00000080 | 0x08000000;
                return value;
            }
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            bool spawn = !instant && preferences.Motion && !preferences.NoIntro && !preferences.NoSitting;
            if (spawn) SpawnInMiddle();
            Play(instant || !preferences.Motion || preferences.NoIntro ? grin : arrive);
            RenderFrame();
            if (!preferences.NoIntro) Static(true, Cue.Arrive, spawn);
            UpdateAnimation();
            if (testing || preferences.Welcomed)
            {
                mainframe.WindowState = FormWindowState.Minimized;
                mainframe.Show();
            }
            else
            {
                mainframe.Restore();
                preferences.Welcomed = true;
                SavePreferences();
            }
            if (!testing) FindBrain();
            if (!testing) DefaultStartup(Installed());
            if (!testing) GreetSoon();
            if (!testing && FreeChatOn) { GetFreeVoice(); GetFreeEars(); }
            // An update can move her HD voice to a new engine: the old pack goes, and with HD on, the new one comes down.
            if (!testing) ThreadPool.QueueUserWorkItem(delegate { qwen.Tidy(); });
            if (!testing && preferences.HdVoice && !qwen.Installed) SetUpHd();
            if (!testing && voice.Key != null) ListVoices(voice.Key, false);
            if (!testing) talkKey = ByMouse(preferences.TalkVk) || Native.RegisterHotKey(Handle, TalkKeyId, preferences.TalkMods | 0x4000, preferences.TalkVk);
            bool muteFree = !testing && (ByMouse(preferences.MuteVk) || (Native.RegisterHotKey(Handle, MuteKeyId, preferences.MuteMods | 0x4000, preferences.MuteVk) && Native.UnregisterHotKey(Handle, MuteKeyId)));
            if (!testing) typeKey = ByMouse(preferences.TypeVk) || Native.RegisterHotKey(Handle, TypeKeyId, preferences.TypeMods | 0x4000, preferences.TypeVk);
            if (!testing) hideKey = ByMouse(preferences.HideVk) || Native.RegisterHotKey(Handle, HideKeyId, preferences.HideMods | 0x4000, preferences.HideVk);
            if (!testing) quietKey = ByMouse(preferences.QuietVk) || Native.RegisterHotKey(Handle, QuietKeyId, preferences.QuietMods | 0x4000, preferences.QuietVk);
            mouseKeys.Tick += delegate { WatchMouseKeys(); };
            WatchMouse();
            mainframe.Hotkeys(TalkKeyName, MuteKeyName, TypeKeyName, HideKeyName, QuietKeyName);
            mainframe.ShowShortcut(talkKey, muteFree);
            mainframe.ShowKeys(typeKey, hideKey, quietKey);
            RefreshIcons();
            if (!testing && !hidden) DropSoon();
            if (!testing && Program.StartedFresh)
            {
                balloonPage = null;
                balloonUpdate = false;
                balloonMainframe = true;
                tray.ShowBalloonTip(12000, "Capri started fresh", "She closed while starting twice in a row, so her settings were reset. Your keys stayed. The old settings are in settings.crashed.json.", ToolTipIcon.Warning);
            }
        }

        // She's been up long enough to count as started, or she's closing cleanly: either way she didn't crash while starting.
        private void Settled()
        {
            if (startMarker == null) return;
            try { File.Delete(startMarker); }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
            startMarker = null;
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            base.OnFormClosing(e);
            // Something outside Capri closing her window, like a pop-up blocker, goes in errors.txt.
            if (!quitting && !testing && e.CloseReason != CloseReason.WindowsShutDown) Brain.Log("quit", -1, "Her window was closed from outside Capri (" + e.CloseReason + ").");
        }

        private void Tick()
        {
            double now = clock.Elapsed.TotalSeconds;
            if (outro != null && now >= outroAt) { Action next = outro; outro = null; next(); }
            if (riding) FollowCursor(); else if (onPanel) HoldPanel(); else if (falling) Tumble(now); else if (seat != null) HoldSeat(now);
            if (walking) Walk(now);
            if (!riding && !dragging && !walking && !falling && outro == null && clip != arrive && clip != leave) Face();
            if (!Steady(now)) RenderFrame();
            if (!riding && !dragging && !walking && outro == null && !preferences.Motion && clip == idle && speech == null && talkState == TalkState.Off) frames.Stop();
            int interval = FrameInterval(now);
            if (frames.Interval != interval) frames.Interval = interval;
        }

        // Her frame timer ticks every 33 ms, except while she sits through her perch at another fps. WinForms timers tick on
        // Windows' 1/64 s clock, so 33 ms really comes every 47 ms; off 30 she asks for just under a whole number of its ticks.
        private int FrameInterval(double now)
        {
            int fps = preferences.PerchFps;
            if (fps == 30 || !SittingStill || (clip != perch && clip != perchDance) || (fps < 30 && (clip != perch || !Quiet(now)))) return 33;
            return Math.Max(1, 64 / fps) * 1000 / 64 - 1;
        }

        // A tick off 30 fps with nothing new to show: she's only sitting, still where she was drawn, and her perch frame hasn't changed.
        private bool Steady(double now)
        {
            int fps = preferences.PerchFps;
            return fps != 30 && clip == perch && SittingStill && Quiet(now) && anchor == drawnAt && facingLeft == drawnFacing && (long)((now - clipStart) * fps) == drawnStep;
        }

        // On a window, not riding, dragged, walking, falling or leaving.
        private bool SittingStill { get { return seat != null && !riding && !dragging && !walking && !falling && outro == null; } }

        // Nothing else about her moves: no words, bubble, typing box or music notes. Her pill only redraws when it changes.
        private bool Quiet(double now) { return speech == null && talkState == TalkState.Off && !box.Visible && !typer.Visible && !notes.Exists(note => now - note.Born < NoteLife); }

        private void Face()
        {
            // Lying, she keeps the way she lay down, which had the room.
            if (lying) return;
            Point hip = Hip();
            int room = Screen.FromPoint(hip).WorkingArea.Right - hip.X;
            bool left = room < preferences.Size * (facingLeft ? 0.9f : 0.6f);
            if (left == facingLeft) return;
            facingLeft = left;
            anchor = new Point(anchor.X + hip.X - Hip().X, anchor.Y);
            Location = anchor;
            Static(false, null);
        }

        private void DropSoon()
        {
            if (clip == arrive) dropAfter = true;
            else if (!Drop()) SavePreferences();
        }

        internal static bool HasArt(string name) { return Assembly.GetExecutingAssembly().GetManifestResourceInfo(name) != null; }

        internal static Bitmap LoadArt(string name)
        {
            using (Stream image = Assembly.GetExecutingAssembly().GetManifestResourceStream(name))
            {
                if (image == null) return null;
                using (Bitmap original = new Bitmap(image))
                {
                    Bitmap copy = new Bitmap(original.Width, original.Height, PixelFormat.Format32bppPArgb);
                    using (Graphics graphics = Graphics.FromImage(copy))
                    {
                        graphics.CompositingMode = CompositingMode.SourceCopy;
                        graphics.DrawImage(original, new Rectangle(0, 0, copy.Width, copy.Height));
                    }
                    return copy;
                }
            }
        }

        private void Play(Clip next)
        {
            clip = next;
            clipStart = clock.Elapsed.TotalSeconds;
            idleCycle = 0;
            perchMix = 0;
            drawnStep = -1;
            blinkWith = null;
            danceLast = -1;
            nodGain = 0;
            veiled = false;
            arrivalDue = next == arrive || next == perchArrive;
        }

        private bool FollowBeat(double now)
        {
            double bpm, beatAt;
            bool locked = groove.Locked(out bpm, out beatAt);
            bool fresh = danceLast < 0 || now - danceLast > 0.5;
            double step = fresh ? 0 : now - danceLast, was = nodGain;
            danceLast = now;
            if (locked) danceBeat = 60 / bpm;
            nodGain = locked ? Math.Min(1, nodGain + step * 2) : Math.Max(0, nodGain - step * 3);
            if ((!locked && nodGain <= 0) || danceBeat <= 0) return false;
            dancePos += step / danceBeat;
            if (locked)
            {
                double off = (now - beatAt) / danceBeat - dancePos;
                off -= Math.Floor(off + 0.5);
                dancePos += fresh || was <= 0 ? off : Math.Max(-0.02, Math.Min(0.02, off));
            }
            bool hit = !fresh && was > 0 && dancePos >= 1;
            dancePos -= Math.Floor(dancePos);
            return hit;
        }

        private void Jam(double now, bool hit)
        {
            notes.RemoveAll(delegate(Note note) { return now - note.Born > NoteLife || now < note.Born; });
            bool due = nodGain > 0.5 ? hit && (danceBeat >= 0.55 || ++noteBeats % 2 == 0) : nodGain <= 0 && now >= nextNote;
            if (!due || notes.Count >= 5) return;
            nextNote = now + 1.3 + random.NextDouble() * 0.6;
            if (random.NextDouble() < 0.75) noteSide = -noteSide;
            notes.Add(new Note { Born = now, Side = noteSide, Shape = random.Next(3), Seed = random.NextDouble() * 100 });
        }

        private float NodDepth()
        {
            if (nodGain <= 0) return 0;
            double rise = dancePos < 0.45 ? 1 - dancePos / 0.45 : 0, fall = dancePos > 0.75 ? (dancePos - 0.75) / 0.25 : 0;
            return (float)(nodGain * (rise * rise + fall * fall));
        }

        private int Advance(double now)
        {
            bool lain = clip == laydown || clip == laydownGlitch || clip == laydownSleep || clip == laydownLeave;
            bool seated = clip == perch || clip == perchGlitch || clip == perchDance || clip == perchArrive || clip == perchLeave || lain;
            bool perched = riding || onPanel || seat != null;
            // Lying needs her ledge still under her: anything else sits her back up first, her hip where it was.
            if (lying && (seat == null || riding || onPanel || walking || falling || hanging || dragging)) SitUp(false);
            if (seated) { if (lying) WarmLie(); else WarmPerch(); }
            if (perched && (!seated || (lain && !lying && clip != laydownLeave)) && !walking) Play(lying ? laydown : perch);
            if ((!perched && seated) || (clip == dangle && !dragging && !falling && !hanging)) Play(idle);
            int index = (int)((now - clipStart) * clip.Fps);
            perchMix = 0;
            if ((clip == perch || clip == perchDance || clip == laydown || clip == laydownSleep) && preferences.PerchFps != 30) index = PerchIndex(now - clipStart, preferences.PerchFps, out perchMix);
            if (clip == leave || clip == perchLeave || clip == laydownLeave) return Math.Min(index, clip.Count - 1);
            if ((clip == glitch && index >= glitch.Count) || (clip == wake && index >= wake.Count) || (clip == grin && index >= grin.Count * 2)) { Play(idle); index = 0; }
            if (clip == arrive && index >= arrive.Count)
            {
                Play(idle);
                index = 0;
                if (dropAfter) { dropAfter = false; if (spawnFall) Fall(); else if (!Drop()) SavePreferences(); }
            }
            if ((clip == perchGlitch && index >= perchGlitch.Count) || (clip == perchArrive && index >= perchArrive.Count)) { Play(perch); index = 0; }
            if (clip == laydownGlitch && index >= laydownGlitch.Count) { Play(laydown); index = 0; }
            if (dropAfter && clip != arrive && clip != glitch)
            {
                dropAfter = false;
                if (!riding && !dragging && !hanging && !hidden && seat == null && !Drop()) SavePreferences();
            }
            if (clip == dance || clip == perchDance) { Jam(now, FollowBeat(now)); return index % clip.Count; }
            if (clip != idle && clip != perch && clip != laydown) return index % clip.Count;
            if (!preferences.Motion) { perchMix = 0; return 0; }
            int cycle = index / clip.Count;
            if (cycle != idleCycle)
            {
                idleCycle = cycle;
                double roll = random.NextDouble();
                blinkWith = roll < 0.1 ? Blinks(true) : roll < 0.55 ? Blinks(false) : null;
                if (now >= nextGlitch && speech == null && talkState == TalkState.Off) { nextGlitch = now + 30 + random.NextDouble() * 30; Play(clip == perch ? perchGlitch : clip == laydown ? laydownGlitch : glitch); return 0; }
            }
            return index % clip.Count;
        }

        // Her blink for the loop she's in, glitchy or not; lying, once those frames are in.
        private Clip Blinks(bool glitchy)
        {
            if (clip == perch) return glitchy ? perchBlinkGlitch : perchBlink;
            if (clip != laydown) return glitchy ? blinkGlitch : blink;
            Clip lain = glitchy ? laydownBlinkGlitch : laydownBlink;
            return lain.Ready(facingLeft) ? lain : null;
        }

        // Her perch frame t seconds into the loop at a given fps, and how much of the frame after it mixes in, in 256ths.
        // The art is 30 fps, so the loop is 2 s at every fps: slower holds each frame a while, faster lands between frames.
        internal static int PerchIndex(double t, int fps, out int mix)
        {
            long step = (long)(t * fps), at = step * 30;
            mix = fps > 30 ? (int)(at % fps * 256 / fps) : 0;
            return (int)(at / fps);
        }

        private void StayOnTop()
        {
            if (!preferences.OnTop || hidden || !IsHandleCreated || menu.Visible || (playerMenu != null && playerMenu.Visible)) return;
            IntPtr foreground = Native.GetForegroundWindow();
            if (foreground == lastForeground && ++topTicks < 8) return;
            lastForeground = foreground;
            topTicks = 0;
            if (player.Visible) Native.SetWindowPos(player.Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            foreach (Form above in new Form[] { pill, box, typer }) if (above.Visible) Native.SetWindowPos(above.Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
        }

        internal static bool UpdateDue(long checkedAt, long now) { return checkedAt <= 0 || now < checkedAt || now - checkedAt >= 3 * TimeSpan.TicksPerHour; }

        internal static bool UpdateDue(long checkedAt, long now, double elapsed, bool started) { return elapsed >= 20 && (!started || UpdateDue(checkedAt, now)); }

        private void CheckForUpdates(bool asked)
        {
            if (Portable.Current != null)
            {
                if (asked) mainframe.UpdateNote("She runs from a USB drive, so she doesn't install updates on other PCs. Swap Capri.exe on the drive for the newest one.", false);
                return;
            }
            if (updating || installing) return;
            updating = true;
            updateStarted = true;
            preferences.UpdateCheckedAt = DateTime.UtcNow.Ticks;
            SavePreferences();
            checkItem.Enabled = false;
            updateItem.Enabled = false;
            if (asked) mainframe.UpdateNote("Checking for updates...", false);
            ThreadPool.QueueUserWorkItem(delegate
            {
                Release found = null;
                UpdateFile ready = null;
                string problem = null;
                try
                {
                    found = updater.Latest();
                    if (UsableRelease(found) && IsNewer(found.Tag, Assembly.GetExecutingAssembly().GetName().Version))
                    {
                        Post(delegate { mainframe.UpdateNote("Downloading Capri " + found.Tag.TrimStart('v', 'V') + "...", false); });
                        ready = updater.Download(found);
                    }
                }
                catch (Exception error) { problem = error is BrainException ? error.Message : found == null ? "Couldn't check for updates. I'll try again in 3 hours." : "Couldn't download the update. I'll try again in 3 hours."; }
                Post(delegate { ShowUpdate(found, ready, problem, asked); });
            });
        }

        internal static Release FetchLatestRelease()
        {
            ServicePointManager.SecurityProtocol |= (SecurityProtocolType)3072;
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create("https://api.github.com/repos/lachydotmcg/capri-desktop/releases/latest");
            request.UserAgent = "Capri-Desktop";
            request.Accept = "application/vnd.github+json";
            request.Timeout = 10000;
            request.ReadWriteTimeout = 10000;
            using (WebResponse response = request.GetResponse())
            using (Stream body = response.GetResponseStream()) return ParseRelease(body);
        }

        internal static Release ParseRelease(Stream body) { return (Release)new DataContractJsonSerializer(typeof(Release)).ReadObject(body); }

        internal static bool IsNewer(string tag, Version current)
        {
            Version found;
            return ReleaseVersion(tag, out found) && found > new Version(current.Major, current.Minor, Math.Max(0, current.Build), Math.Max(0, current.Revision));
        }

        internal static bool ReleaseVersion(string tag, out Version version)
        {
            version = null;
            if (tag == null || !Regex.IsMatch(tag, @"^[vV]?\d+\.\d+(\.\d+){0,2}$") || !Version.TryParse(tag.TrimStart('v', 'V'), out version)) return false;
            version = new Version(version.Major, version.Minor, Math.Max(0, version.Build), Math.Max(0, version.Revision));
            return true;
        }

        private static bool UsableRelease(Release found)
        {
            Version version;
            return found != null && !found.Draft && !found.Prerelease && ReleaseVersion(found.Tag, out version);
        }

        private void ShowUpdate(Release found, UpdateFile ready, string problem, bool asked)
        {
            updating = false;
            checkItem.Enabled = true;
            updateItem.Enabled = updateFile != null;
            Version current = Assembly.GetExecutingAssembly().GetName().Version;
            if (problem != null) { ForgetUpdate(); mainframe.UpdateNote(problem, true); return; }
            if (ready != null)
            {
                bool fresh = updateFile == null || updateFile.Path != ready.Path;
                updateFile = ready;
                updateItem.Enabled = true;
                updateItem.Text = "Restart to update to Capri " + ready.Version;
                if (!menu.Items.Contains(updateItem)) menu.Items.Insert(menu.Items.Count - 2, updateItem);
                mainframe.UpdateNote(updateItem.Text + ". Use her tray menu.", false);
                if (fresh || asked)
                {
                    balloonPage = null;
                    balloonUpdate = true;
                    balloonMainframe = false;
                    tray.BalloonTipTitle = "Capri update ready";
                    tray.BalloonTipText = updateItem.Text;
                    tray.BalloonTipIcon = ToolTipIcon.Info;
                    if (!testing) tray.ShowBalloonTip(8000);
                }
                return;
            }
            ForgetUpdate();
            if (asked || !UsableRelease(found)) mainframe.UpdateNote(UsableRelease(found) ? "You're on the latest version (" + current.ToString(3) + ")." : "Couldn't check for updates. I'll try again in 3 hours.", !UsableRelease(found));
        }

        private void BalloonClicked()
        {
            if (balloonUpdate) InstallUpdate();
            else if (balloonPage != null) OpenPage(balloonPage);
            else if (balloonMainframe) mainframe.Restore();
        }

        private void ForgetUpdate()
        {
            updateFile = null;
            updateItem.Enabled = false;
            menu.Items.Remove(updateItem);
            balloonUpdate = false;
        }

        private void InstallUpdate()
        {
            if (updating || installing || updateFile == null) return;
            installing = true;
            updateItem.Enabled = false;
            checkItem.Enabled = false;
            UpdateFile ready = updateFile;
            int parent;
            long started;
            using (Process process = Process.GetCurrentProcess()) { parent = process.Id; started = process.StartTime.ToUniversalTime().Ticks; }
            mainframe.UpdateNote("Checking the update before restarting...", false);
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem = null;
                bool invalid = false;
                try { updater.Install(ready, parent, started); }
                catch (Exception error)
                {
                    invalid = error is BrainException || !File.Exists(ready.Path);
                    problem = error is BrainException ? error.Message : UpdateProblem(error);
                    Brain.Log("update", -1, error.GetType().Name + ": " + error.Message);
                }
                Post(delegate
                {
                    installing = false;
                    checkItem.Enabled = true;
                    updateItem.Enabled = true;
                    if (problem != null) { if (invalid) ForgetUpdate(); mainframe.UpdateNote(problem, true); return; }
                    updateExit();
                });
            });
        }

        // Why the installer didn't start, so they know what to do next.
        internal static string UpdateProblem(Exception error)
        {
            System.ComponentModel.Win32Exception windows = error as System.ComponentModel.Win32Exception;
            int code = windows == null ? 0 : windows.NativeErrorCode;
            if (code == 1223) return "The update needs a Yes in the Windows prompt. Try again.";
            if (code == 225 || code == 226) return "Your antivirus blocked the update. Capri is still running.";
            return "Couldn't start the update (" + Voice.Short(error.Message).TrimEnd('.') + "). Capri is still running.";
        }

        private static void OpenPage(string page)
        {
            if (page != OllamaPage && page != FreeKeyPage && page != GuidePage && page != DiscordPage && page != HelpPage) return;
            Browse(page);
        }

        private void CheckIdle(long quiet)
        {
            // A hide they asked for waits until she's said her line.
            if (hideAsked && !hidden && !dragging && !pressed && speech == null && talkState != TalkState.Thinking && talkState != TalkState.Talking && clock.Elapsed.TotalSeconds >= voiceUntil && !speaker.Busy) { hideAsked = false; SetHidden(true); return; }
            // A click, a drag or talking to her took her out of the nap they asked for.
            if (napping && !Asleep) napping = false;
            if (napAsked && ((clip == idle && seat == null && !onPanel) || (clip == laydown && lying)) && !dragging && !pressed && !riding && !walking && !falling && !hanging
                && speech == null && talkState != TalkState.Thinking && talkState != TalkState.Talking && clock.Elapsed.TotalSeconds >= voiceUntil && !speaker.Busy)
            {
                napAsked = false;
                napping = true;
                StopChat();
                Play(lying ? laydownSleep : sleep);
                frames.Start();
                return;
            }
            // After setup, once she's said hi and her bubble's gone, she gets to know them.
            if (meetAt >= 0 && clock.Elapsed.TotalSeconds >= meetAt && !hidden && !dragging && !pressed && !chatting && !typer.Visible && !Asleep && !napAsked && !napping
                && speech == null && talkState == TalkState.Off && clock.Elapsed.TotalSeconds >= voiceUntil && !speaker.Busy)
            {
                meetAt = -1;
                GetToKnow();
                return;
            }
            if (clip == sleep) { if (quiet < 1000 && !napping) Play(wake); return; }
            if (clip == laydownSleep) { if (quiet < 1000 && !napping) Play(laydown); return; }
            bool drowsy = SleepDue(quiet) && preferences.Motion && !riding && !dragging && !hidden && !chatting && speech == null && talkState == TalkState.Off && !typer.Visible;
            if (drowsy && clip == idle) Play(sleep);
            // On a ledge with room she lies down first, then dozes off where she lies.
            else if (drowsy && clip == laydown && lying) Play(laydownSleep);
            else if (drowsy && clip == perch && SittingStill) LieDown();
        }

        // "Go to sleep" from her menu, her brain or plain words: she lies down along her ledge if it has room, or else gets down
        // from wherever she is, finishes what she's saying, then sleeps there. Unlike the doze she falls into by herself, their
        // mouse and keyboard don't wake her.
        internal string Nap(bool sleeping)
        {
            if (!sleeping)
            {
                bool resting = napAsked || napping || Asleep;
                napAsked = false;
                napping = false;
                if (clip == sleep) { Play(wake); frames.Start(); }
                else if (clip == laydownSleep) { Play(laydown); frames.Start(); }
                return resting ? "Woke up." : "Already awake.";
            }
            if (hidden) SetHidden(false);
            if (riding) StopRide();
            EndWalk();
            danceAsked = false;
            if (clip == perchDance) Play(perch);
            // On a ledge with room she lies down to sleep along it; anywhere else she gets down and sleeps where she floats.
            if (hanging || (seat != null && !lying && !LieDown())) StandUp();
            if (clip == dance || clip == perchDance) Play(idle);
            napAsked = true;
            return "Going to sleep. A click on me wakes me up.";
        }

        // Her nap tool, which her brain calls from its own thread.
        private string NapTool(bool sleeping) { return InvokeRequired ? (string)Invoke(new Func<bool, string>(Nap), sleeping) : Nap(sleeping); }

        // Her own moves, from her brain, plain words or her Move menu: "teleport here" glitches her over to their mouse, "go to my
        // other monitor" to the same spot on another screen, "sit on my Roblox window" onto its top edge, and she sits, lies down
        // and sits up, stands, walks around, wanders off, hangs, rides their cursor, hides and comes back. move_mainframe takes
        // her Mainframe to another screen, or over to their mouse. `screen` is the window they named for sit_on and lie_down.
        internal string MoveSelf(string action, string screen)
        {
            lieBy = -1;
            if (action == "move_mainframe") return MoveMainframe(screen);
            if (action == "hide")
            {
                if (hidden) return "Already hidden.";
                hideAsked = true;
                return "Hiding. " + (hideKey ? HideKeyName + " or a double-click" : "A double-click") + " on my tray icon brings me back.";
            }
            hideAsked = false;
            if (action == "show")
            {
                if (!hidden) return "I'm right here.";
                ShowHidden(false);
                DropSoon();
                return "Back.";
            }
            napAsked = false;
            napping = false;
            if (action == "come_here")
            {
                Teleport(MouseAt());
                return "Teleporting to your mouse.";
            }
            if (action == "other_screen")
            {
                Screen[] screens = Screen.AllScreens;
                Screen from = Screen.FromPoint(Hip());
                int to = PickScreen(screens, from, screen);
                if (to < 0) return screens.Length < 2 ? "There's no other screen to go to." : "There's no screen like that to go to.";
                if (screens[to].DeviceName == from.DeviceName) return "I'm already on " + ScreenName(screens, to) + ".";
                Teleport(Across(Hip(), from.WorkingArea, screens[to].WorkingArea));
                return "Moving to " + ScreenName(screens, to) + ".";
            }
            if (hidden) ShowHidden(false);
            if (action == "sit_on") return SitOn(screen, false);
            if (action == "lie_down") return string.IsNullOrWhiteSpace(screen) ? LieHere() : SitOn(screen, true);
            if (action == "walk_around") return WalkAround();
            if (action == "wander")
            {
                if (Spots().Count == 0) return "There's nowhere else to go right now.";
                StopRide();
                LeavePanel(false);
                hanging = false;
                danceAsked = false;
                Wander();
                return "Off somewhere else.";
            }
            if (action == "sit_up" || (action == "sit" && lying))
            {
                if (!lying) return seat != null && !seat.Free ? "Already sitting up." : "I'm not lying down.";
                SitUp();
                return "Sitting up.";
            }
            if (action == "sit")
            {
                if (seat != null && seat.Free) return "Already sitting.";
                StopRide();
                LeavePanel(false);
                SitHere();
                return "Sitting right here.";
            }
            if (action == "stand_up")
            {
                if (riding) { StopRide(); return "Hopped off your cursor."; }
                if (hanging) { LetGo(); return "Let go."; }
                if (seat == null) return "Already standing.";
                StandUp();
                return "Standing up.";
            }
            if (action == "hang")
            {
                if (hanging) return "Already hanging.";
                StopRide();
                LeavePanel(false);
                HangHere();
                return "Hanging right here.";
            }
            if (action == "ride_cursor")
            {
                if (riding) return "Already riding your cursor.";
                StartRide(true);
                if (!riding) return "Couldn't get on your cursor just now.";
                return "Riding your cursor. " + (hotkey ? hopName + " or \"hop off my cursor\" gets" : "\"Hop off my cursor\" gets") + " me off.";
            }
            if (action == "hop_off")
            {
                if (!riding) return "I'm not riding your cursor.";
                StopRide();
                return "Hopped off your cursor.";
            }
            return "Couldn't move like that.";
        }

        private string MoveTool(string action, string screen) { return InvokeRequired ? (string)Invoke(new Func<string, string, string>(MoveSelf), action, screen) : MoveSelf(action, screen); }

        // "Sit on my Roblox window": she glitches over onto the top edge of the window they named, the front one when several
        // match, or onto the taskbar or her Mainframe. Told to lie down there, she lies along it once she's sitting. A window
        // that's minimized, fills the screen or has its top edge covered has nowhere to sit, and she says so.
        private string SitOn(string wanted, bool lie)
        {
            string name = Regex.Replace((wanted ?? "").Trim(), @"^(?:the|my|your|ur|our|that|this) | (?:window|app|application|game|tab)$", "", RegexOptions.IgnoreCase).Trim();
            if (name.Length == 0) return "Which window, choom?";
            System.Collections.Generic.List<Ledge> around = Around();
            System.Collections.Generic.List<Ledge> spots;
            string shown, why = null;
            if (Hands.TaskbarWords.IsMatch(name))
            {
                Rectangle area = Screen.FromPoint(Hip()).WorkingArea;
                spots = around.FindAll(ledge => ledge.Floor && ledge.Y == area.Bottom && ledge.Left == area.Left);
                shown = "the taskbar";
            }
            else if (Hands.MainframeWords.IsMatch(name))
            {
                if (!mainframe.IsHandleCreated || !mainframe.Visible || mainframe.WindowState != FormWindowState.Normal) return "My Mainframe isn't open. Open it and I'll sit on it.";
                IntPtr own = mainframe.Handle;
                spots = around.FindAll(ledge => ledge.Window == own);
                shown = "my Mainframe";
                why = "There's no room for me on top of my Mainframe: something's covering it, or it's too close to the top of the screen.";
            }
            else
            {
                string called = char.ToUpperInvariant(name[0]) + name.Substring(1);
                System.Collections.Generic.List<OpenWindow> found = Hands.WindowsNamed(name);
                if (found.Count == 0) return Hands.Unlisted() ?? "I can't see " + called + " open.";
                shown = "your " + called + " window";
                spots = new System.Collections.Generic.List<Ledge>();
                foreach (OpenWindow window in found)
                {
                    Rectangle bounds;
                    IntPtr handle = window.Handle;
                    if (!Ledges.Showing(handle, out bounds)) { why = why ?? called + " is minimized. Open it and I'll sit on it."; continue; }
                    if (!Ledges.Seatable(handle, bounds)) { why = why ?? (bounds.Width < 120 || bounds.Height < 60 ? called + " is too small to sit on." : called + " fills the screen, so its top edge is off the top. Make it smaller and I'll sit on it."); continue; }
                    spots = around.FindAll(ledge => ledge.Window == handle);
                    if (spots.Count > 0) break;
                    why = why ?? "Other windows are covering the top of " + shown + ".";
                }
            }
            int room = Headroom();
            spots.RemoveAll(ledge => !ledge.Icon.IsEmpty || ledge.Right - ledge.Left < 24 || ledge.Y - room < Screen.FromPoint(new Point(ledge.Left, ledge.Y)).Bounds.Top);
            if (spots.Count == 0) return why ?? "There's no room for me on top of " + shown + ".";
            Ledge spot = spots[0];
            foreach (Ledge each in spots) if (each.Right - each.Left > spot.Right - spot.Left) spot = each;
            bool there = seat != null && !seat.Free && seat.Icon.IsEmpty && !riding && !walking && !falling && (spot.Floor ? seat.Floor && seat.Y == spot.Y && seat.Left == spot.Left : seat.Window == spot.Window);
            if (there) return lie ? LieHere(shown) : "Already sitting on " + shown + ".";
            int margin = Math.Min(preferences.Size / 4, (spot.Right - spot.Left) / 3);
            int x = spot.Left + margin + random.Next(Math.Max(1, spot.Right - spot.Left - 2 * margin));
            StopRide();
            LeavePanel(false);
            hanging = false;
            danceAsked = false;
            GlitchOut(delegate { Hop(spot, x); }, false);
            if (lie) lieBy = clock.Elapsed.TotalSeconds + 10;
            return (lie ? "Lying down on " : "Sitting on ") + shown + ".";
        }

        // "Lie down": along the ledge she sits on, if it has room. Anywhere else, like mid-air, she drops onto whatever is under
        // her and lies down there.
        private string LieHere(string shown = null)
        {
            string done = shown == null ? "Lying down." : "Lying down on " + shown + ".";
            if (lying) return "Already lying down.";
            StopRide();
            LeavePanel(false);
            EndWalk();
            danceAsked = false;
            if (clip == perchDance) Play(perch);
            if (seat != null && !seat.Free && seat.Icon.IsEmpty && !falling)
            {
                // Still glitching onto it: she lies down once she's sat.
                if (clip != perch) { lieBy = clock.Elapsed.TotalSeconds + 10; return done; }
                return LieDown() ? done : "There's no room to lie down here. Try \"lie down on the taskbar\".";
            }
            if (seat != null) StandUp();
            hanging = false;
            Ledge under = Ledges.Below(Around(), Hip(), 0, int.MaxValue, 0, Headroom());
            if (under == null) return "There's nothing under me to lie on.";
            lieBy = clock.Elapsed.TotalSeconds + 10;
            falling = true;
            fallTo = under;
            fallSpeed = 0;
            fallStep = clock.Elapsed.TotalSeconds;
            frames.Start();
            return done;
        }

        // "Walk around": a stroll along her window or the taskbar, or through the air where she floats. With no room for one she
        // wanders off to another window instead.
        private string WalkAround()
        {
            if (walking) return "Already walking.";
            StopRide();
            LeavePanel(false);
            danceAsked = false;
            SitUp(false);
            if (hanging) { hanging = false; Play(idle); }
            if (clip == perchDance) Play(perch);
            else if (clip == dance) Play(idle);
            if (Stroll()) return "Going for a little walk.";
            if (Spots().Count == 0) return "There's no room to walk around here.";
            Wander();
            return "Wandering off somewhere.";
        }

        // She glitches out and back in with her hip on the point, kept on its screen, then drops onto a window close under her.
        private void Teleport(Point to)
        {
            Rectangle area = Screen.FromPoint(to).WorkingArea;
            Action arrive = delegate
            {
                StopRide();
                LeavePanel(false);
                seat = null;
                hanging = false;
                falling = false;
                walking = false;
                anchor = Within(Seated(to.X, to.Y), area, Body);
                ShowHidden(false);
                DropSoon();
            };
            if (hidden) arrive();
            else GlitchOut(arrive, false);
        }

        // Which of their screens "next", "left", "main", "here" or "2" means, from the given one, or -1.
        private static int PickScreen(Screen[] screens, Screen from, string which)
        {
            int[] x = new int[screens.Length], y = new int[screens.Length], numbers = new int[screens.Length];
            int primary = 0, current = -1, pointed = -1;
            Screen mouse = Screen.FromPoint(MouseAt());
            for (int i = 0; i < screens.Length; i++)
            {
                Rectangle bounds = screens[i].Bounds;
                x[i] = bounds.Left + bounds.Width / 2;
                y[i] = bounds.Top + bounds.Height / 2;
                Match digits = Regex.Match(screens[i].DeviceName ?? "", @"(\d+)$");
                numbers[i] = digits.Success && digits.Length < 3 ? int.Parse(digits.Value) : 0;
                if (screens[i].Primary) primary = i;
                if (screens[i].DeviceName == from.DeviceName) current = i;
                if (screens[i].DeviceName == mouse.DeviceName) pointed = i;
            }
            return Hands.PickScreen(x, y, numbers, primary, current, pointed, which);
        }

        private static string ScreenName(Screen[] screens, int index)
        {
            if (screens[index].Primary) return "your main screen";
            Match digits = Regex.Match(screens[index].DeviceName ?? "", @"(\d+)$");
            return screens.Length == 2 || !digits.Success ? "your other screen" : "screen " + digits.Value;
        }

        // The same spot on another screen: as far across and down its working area as it was on the first.
        internal static Point Across(Point at, Rectangle from, Rectangle to)
        {
            double across = from.Width > 0 ? Math.Max(0, Math.Min(1, (at.X - from.Left) / (double)from.Width)) : 0.5;
            double down = from.Height > 0 ? Math.Max(0, Math.Min(1, (at.Y - from.Top) / (double)from.Height)) : 0.5;
            return new Point(to.Left + (int)Math.Round(across * to.Width), to.Top + (int)Math.Round(down * to.Height));
        }

        // A window as far across and down another working area as it was on its own, kept inside it where it fits.
        internal static Rectangle Shifted(Rectangle window, Rectangle from, Rectangle to)
        {
            double across = from.Width > window.Width ? Math.Max(0, Math.Min(1, (window.Left - from.Left) / (double)(from.Width - window.Width))) : 0.5;
            double down = from.Height > window.Height ? Math.Max(0, Math.Min(1, (window.Top - from.Top) / (double)(from.Height - window.Height))) : 0.5;
            return Placed(new Rectangle(to.Left + (int)Math.Round(across * (to.Width - window.Width)), to.Top + (int)Math.Round(down * (to.Height - window.Height)), window.Width, window.Height), to);
        }

        // A window moved inside a working area, its top left corner first when it's bigger.
        internal static Rectangle Placed(Rectangle window, Rectangle area)
        {
            return new Rectangle(Math.Max(area.Left, Math.Min(window.Left, area.Right - window.Width)), Math.Max(area.Top, Math.Min(window.Top, area.Bottom - window.Height)), window.Width, window.Height);
        }

        // "Move the Mainframe to my other monitor": the same part of another screen, or centred on their mouse for "bring it
        // here". It comes up from the taskbar too, since moving it somewhere unseen would do nothing for them.
        private string MoveMainframe(string which)
        {
            Screen[] screens = Screen.AllScreens;
            bool normal = mainframe.WindowState == FormWindowState.Normal;
            Rectangle bounds = normal ? mainframe.Bounds : mainframe.RestoreBounds;
            Screen from = Screen.FromRectangle(bounds);
            bool here = Regex.IsMatch(which ?? "", @"^\s*(here|this|mouse|cursor|pointer)\s*$", RegexOptions.IgnoreCase);
            int to = PickScreen(screens, from, which);
            if (to < 0) return screens.Length < 2 ? "There's no other screen for the Mainframe." : "There's no screen like that for the Mainframe.";
            Rectangle moved;
            if (here)
            {
                Point mouse = MouseAt();
                moved = Placed(new Rectangle(mouse.X - bounds.Width / 2, mouse.Y - bounds.Height / 2, bounds.Width, bounds.Height), screens[to].WorkingArea);
            }
            else if (screens[to].DeviceName == from.DeviceName)
            {
                if (!testing) mainframe.Restore();
                return "The Mainframe's already on " + ScreenName(screens, to) + ".";
            }
            else moved = Shifted(bounds, from.WorkingArea, screens[to].WorkingArea);
            bool maximized = mainframe.WindowState == FormWindowState.Maximized;
            if (!normal) mainframe.WindowState = FormWindowState.Normal;
            mainframe.Bounds = moved;
            if (maximized) mainframe.WindowState = FormWindowState.Maximized;
            if (!testing) mainframe.Restore();
            return here ? "Brought the Mainframe over to your mouse." : "Moved the Mainframe to " + ScreenName(screens, to) + ".";
        }

        // Her animations by name, from her brain, plain words or her Move menu's Dance. A dance goes on, with or without music,
        // until they say stop.
        internal string Animate(string name)
        {
            if (name == "stop_dancing")
            {
                bool was = danceAsked || clip == dance || clip == perchDance;
                danceAsked = false;
                danceHeld = musicOn;
                if (clip == dance || clip == perchDance) { Play(seat != null || onPanel ? perch : idle); UpdateAnimation(); }
                return was ? "Stopped dancing." : "I wasn't dancing.";
            }
            napAsked = false;
            napping = false;
            if (hidden) ShowHidden(false);
            if (name == "dance")
            {
                StopRide();
                if (hanging) LetGo();
                danceAsked = true;
                danceHeld = false;
                frames.Start();
                return "Dancing. Tell me to stop when you've had enough.";
            }
            bool perched = seat != null || onPanel || riding;
            if (name == "idle")
            {
                danceAsked = false;
                danceHeld = musicOn;
                if (hanging) LetGo();
                Play(perched ? perch : idle);
            }
            else if (name == "glitch")
            {
                if (hanging) LetGo();
                else Play(perched ? perchGlitch : glitch);
            }
            else if (name == "grin")
            {
                // Her grin is a standing one, so she gets up for it.
                if (riding) StopRide();
                else
                {
                    LeavePanel(false);
                    if (hanging) LetGo();
                    else if (seat != null) StandUp();
                    Play(grin);
                }
            }
            else if (name == "blink")
            {
                if (hanging) LetGo();
                Play(perched ? perch : idle);
                blinkWith = perched ? perchBlink : blink;
            }
            else return "I don't have an animation called " + name + ".";
            frames.Start();
            RenderFrame();
            return name == "idle" ? "Back to my idle." : name == "glitch" ? "Glitched." : name == "grin" ? "Grinning." : "Blinked.";
        }

        private string AnimateTool(string name) { return InvokeRequired ? (string)Invoke(new Func<string, string>(Animate), name) : Animate(name); }

        private static Size CanvasSize(int size) { return new Size(size + PaddingSize * 2, size + PaddingSize * 2); }

        private void AddSize(ToolStripMenuItem parent, string label, int size)
        {
            ToolStripMenuItem item = new ToolStripMenuItem(label, null, delegate { SetCharacterSize(size); });
            item.Tag = size;
            item.Checked = preferences.Size == size;
            parent.DropDownItems.Add(item);
        }

        internal void SetCharacterSize(int size)
        {
            size = Math.Max(MinSize, Math.Min(MaxSize, size));
            EndWalk();
            Point center = new Point(anchor.X + Width / 2, anchor.Y + Height / 2);
            int hipX = Hip().X;
            preferences.Size = size;
            Size = CanvasSize(size);
            anchor = seat != null ? Seated(hipX, seat.Y) : KeepOnScreen(new Point(center.X - Width / 2, center.Y - Height / 2));
            Location = anchor;
            foreach (ToolStripItem entry in menu.Items)
            {
                ToolStripMenuItem group = entry as ToolStripMenuItem;
                if (group == null || group.Text != "Size") continue;
                foreach (ToolStripMenuItem option in group.DropDownItems) option.Checked = (int)option.Tag == size;
            }
            RenderFrame();
            SavePreferences();
            mainframe.Sync();
        }

        private Point KeepOnScreen(Point point) { return Within(point, Screen.FromPoint(new Point(point.X + Width / 2, point.Y + Height / 2)).WorkingArea, Body); }

        private Point Within(Point point, Rectangle area, RectangleF body)
        {
            int size = preferences.Size;
            int left = area.Left - PaddingSize - (int)(size * body.Left);
            int right = area.Right - PaddingSize - (int)Math.Ceiling(size * body.Right);
            int top = area.Top - PaddingSize - (int)(size * body.Top);
            int bottom = area.Bottom - PaddingSize - (int)Math.Ceiling(size * body.Bottom);
            return new Point(Math.Max(left, Math.Min(point.X, right)), Math.Max(top, Math.Min(point.Y, bottom)));
        }

        private Rectangle BodyOnScreen(Point point, RectangleF body)
        {
            int size = preferences.Size;
            return Rectangle.FromLTRB(point.X + PaddingSize + (int)(size * body.Left), point.Y + PaddingSize + (int)(size * body.Top), point.X + PaddingSize + (int)Math.Ceiling(size * body.Right), point.Y + PaddingSize + (int)Math.Ceiling(size * body.Bottom));
        }

        private void DisplaysChanged(object sender, EventArgs e)
        {
            if (IsDisposed) return;
            BeginInvoke((Action)delegate { if (seat != null) StandUp(); anchor = KeepOnScreen(anchor); Location = anchor; RenderFrame(); });
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left || outro != null) return;
            pressed = true;
            dragging = false;
            pointerStart = Cursor.Position;
            anchorStart = anchor;
            Capture = true;
        }

        private void MovePointer(Point position)
        {
            if (!pressed) return;
            int dx = position.X - pointerStart.X;
            int dy = position.Y - pointerStart.Y;
            if (!dragging && dx * dx + dy * dy < 25) return;
            if (onPanel)
            {
                // During a job dragging her carries the task panel she's sitting on.
                if (!dragging) panelGrabbed = taskPanel.Location;
                dragging = true;
                pendingClick = false;
                clickDelay.Stop();
                taskPanel.MoveTo(new Point(panelGrabbed.X + dx, panelGrabbed.Y + dy));
                return;
            }
            // Picked up lying, she sits up first, so she hangs from the cursor where her hip was.
            if (!dragging && lying) { int was = anchor.X; SitUp(false); anchorStart.X += anchor.X - was; }
            if (!dragging) { seat = null; falling = false; hanging = false; walking = false; dropAfter = false; leanAngle = 0; Play(dangle); frames.Start(); RefreshIcons(); }
            dragging = true;
            pendingClick = false;
            clickDelay.Stop();
            anchor = KeepOnScreen(new Point(anchorStart.X + dx, anchorStart.Y + dy));
            Location = anchor;
        }

        protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); MovePointer(Cursor.Position); Stroke(Cursor.Position); }

        private void Stroke(Point cursor)
        {
            if (pressed || dragging || riding || hidden || chatting || working != null || frame == null || !Solid(PointToClient(cursor))) { petTurns.Clear(); petWay = 0; return; }
            int dx = cursor.X - petX;
            if (Math.Abs(dx) < 6) return;
            long now = clock.ElapsedMilliseconds;
            int way = Math.Sign(dx);
            petX = cursor.X;
            if (petWay != 0 && way != petWay) petTurns.Add(now);
            petWay = way;
            petTurns.RemoveAll(delegate(long at) { return now - at > 1500; });
            if (petTurns.Count < 4 || now - petAt < 20000) return;
            petTurns.Clear();
            petAt = now;
            Petted();
        }

        private void Petted()
        {
            EndWalk();
            if (lying) { Play(laydown); blinkWith = Blinks(false); }
            else if (seat != null) { Play(perch); blinkWith = perchBlink; }
            else Play(grin);
            frames.Start();
            RenderFrame();
            int ticket = ++petTicket;
            ThreadPool.QueueUserWorkItem(delegate { Thread.Sleep(PetPause); Post(delegate { PetLine(ticket); }); });
        }

        private void GreetSoon()
        {
            int ticket = asking;
            ThreadPool.QueueUserWorkItem(delegate { Thread.Sleep(GreetPause); Post(delegate { Greet(ticket, DateTime.Now); }); });
        }

        // On a holiday her hello is its line, in her voice, since there's no recording of it.
        private void Greet(int ticket, DateTime now)
        {
            greetTried = true;
            string[] holiday = Brain.Holiday(now);
            string line = holiday != null ? holiday[random.Next(holiday.Length)] : Brain.Greeting(now.Hour);
            if (line == null || ticket != asking || hidden || chatting || speech != null || talkState != TalkState.Off || typer.Visible) return;
            heard = "startup";
            box.Prompt = "> sys: ";
            if (holiday != null) holidaySaid = now.Date;
            byte[] hello = holiday != null ? null : Hello(Brain.GreetingClip(now.Hour));
            if (hello == null) Answer(++asking, line, TalkState.Talking);
            else Begin(++asking, line, TalkState.Talking, hello);
        }

        // The day she last wished them a happy holiday, and whether her startup hello has had its turn.
        private DateTime holidaySaid;
        private bool greetTried;

        // Already running on a holiday, like through midnight into Halloween (Lachy, 30 Oct: "check time and say Happy Halloween
        // on the 31st"), she says its line once that day, the first time she's free while they're at the PC.
        private void CheckHoliday(DateTime now, long quiet)
        {
            string[] holiday = Brain.Holiday(now);
            if (holiday == null || now.Date == holidaySaid || !greetTried) return;
            if (quiet > 60000 || Hushed || hidden || quitting || dragging || pressed || chatting || typer.Visible || menu.Visible || speech != null || talkState != TalkState.Off || outro != null || onPanel || popOut >= 0 || working != null || FullScreen()) return;
            holidaySaid = now.Date;
            Remark("holiday", holiday[random.Next(holiday.Length)]);
        }

        internal static byte[] Hello(string name)
        {
            using (Stream clip = Assembly.GetExecutingAssembly().GetManifestResourceStream("Capri.Voice.hello-" + name + ".wav"))
            {
                if (clip == null) return null;
                using (MemoryStream copy = new MemoryStream()) { clip.CopyTo(copy); return copy.ToArray(); }
            }
        }

        private void PetLine(int ticket)
        {
            if (ticket != petTicket || hidden || chatting || speech != null || talkState != TalkState.Off || typer.Visible) return;
            heard = "pets you";
            box.Prompt = "> sys: ";
            // Pat lines use the same voice as everything else she says: their ElevenLabs voice and model when they've set one.
            Answer(++asking, NextPetLine(), TalkState.Talking);
        }

        internal string NextPetLine()
        {
            if (petBag.Count == 0)
            {
                for (int i = 0; i < PetLines.Length; i++) petBag.Insert(random.Next(petBag.Count + 1), i);
                if (petBag[0] == lastPet) { petBag[0] = petBag[petBag.Count - 1]; petBag[petBag.Count - 1] = lastPet; }
            }
            lastPet = petBag[0];
            petBag.RemoveAt(0);
            return PetLines[lastPet];
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (e.Button == MouseButtons.Right) { menu.Show(Cursor.Position); return; }
            if (e.Button != MouseButtons.Left || !pressed) return;
            pressed = false;
            Capture = false;
            if (dragging)
            {
                pendingClick = false;
                clickDelay.Stop();
                // On the panel she stays sitting on it, wherever they carried it.
                if (!onPanel)
                {
                    // Smoke tests ignore the real keyboard, so someone typing a capital mid-test can't make her sit.
                    Keys held = testing ? Keys.None : ModifierKeys;
                    if ((held & Keys.Control) != 0) HangHere();
                    else if ((held & Keys.Shift) != 0) SitHere();
                    else if (!Drop()) SavePreferences();
                }
            }
            // Where the click happened, not where the mouse is by now.
            else if (pendingClick && IsDoubleClick(pendingPoint, PointToScreen(e.Location), clock.ElapsedMilliseconds - pendingTime)) { pendingClick = false; clickDelay.Stop(); StartRide(); }
            else { pendingClick = true; pendingPoint = PointToScreen(e.Location); pendingTime = clock.ElapsedMilliseconds; clickDelay.Stop(); clickDelay.Start(); }
            dragging = false;
        }

        protected override void OnMouseCaptureChanged(EventArgs e) { base.OnMouseCaptureChanged(e); if (!Capture) pressed = false; }

        protected override void WndProc(ref Message message)
        {
            if (message.Msg == 0x0084 && frame != null)
            {
                long value = message.LParam.ToInt64();
                Point point = PointToClient(new Point((short)(value & 65535), (short)((value >> 16) & 65535)));
                if (!Solid(point))
                {
                    message.Result = new IntPtr(-1);
                    return;
                }
            }
            if (message.Msg == 0x0312 && message.WParam.ToInt32() == DismountId) { StopRide(); return; }
            if (message.Msg == 0x0312 && message.WParam.ToInt32() == TalkKeyId) { if (hidden) SetHidden(false); ToggleChat(); return; }
            if (message.Msg == 0x0312 && message.WParam.ToInt32() == MuteKeyId) { ToggleMic(); return; }
            if (message.Msg == 0x0312 && message.WParam.ToInt32() == TypeKeyId) { if (hidden) SetHidden(false); OpenTyper(); return; }
            if (message.Msg == 0x0312 && message.WParam.ToInt32() == HideKeyId) { ToggleHidden(); return; }
            if (message.Msg == 0x0312 && message.WParam.ToInt32() == QuietKeyId) { ToggleShush(); return; }
            if (message.Msg == 0x02E0) { anchor = KeepOnScreen(anchor); Location = anchor; RenderFrame(); }
            base.WndProc(ref message);
        }

        private bool Solid(Point point, bool uncovered = false)
        {
            for (int dx = -4; dx <= 4; dx += 4)
                for (int dy = -4; dy <= 4; dy += 4)
                {
                    int x = point.X + dx;
                    int y = point.Y + dy;
                    if (x >= 0 && y >= 0 && x < frame.Width && y < frame.Height && frame.GetPixel(x, y).A >= 12 && (!uncovered || Uncovered(PointToScreen(new Point(x, y))))) return true;
                }
            return false;
        }

        private void OnClickDelay()
        {
            clickDelay.Stop();
            if (!pendingClick) return;
            pendingClick = false;
            if (hidden || riding || dragging || pressed) return;
            React();
        }

        internal static bool IsDoubleClick(Point a, Point b, long elapsed)
        {
            Size box = SystemInformation.DoubleClickSize;
            return elapsed >= 0 && elapsed <= SystemInformation.DoubleClickTime && Math.Abs(a.X - b.X) <= box.Width / 2 && Math.Abs(a.Y - b.Y) <= box.Height / 2;
        }

        private void StartRide(bool quiet = false)
        {
            if (riding || hidden || !IsHandleCreated) return;
            Halt();
            LeavePanel(false);
            dropAfter = false;
            pendingClick = false;
            clickDelay.Stop();
            pressed = false;
            dragging = false;
            Capture = false;
            seat = null;
            falling = false;
            hanging = false;
            walking = false;
            hopName = null;
            for (int i = 0; i < HopNames.Length && hopName == null; i++)
                if (Native.RegisterHotKey(Handle, DismountId, HopKeys[i, 0] | 0x4000, HopKeys[i, 1])) hopName = HopNames[i];
            hotkey = hopName != null;
            riding = true;
            Native.SetWindowLong(Handle, -20, Native.GetWindowLong(Handle, -20) | 0x20);
            rideItem.Text = "Hop off";
            tray.Text = hotkey ? "Capri · " + hopName + " to hop off" : "Capri · Hop off from this menu";
            if (!testing && !quiet) { balloonPage = null; balloonUpdate = false; balloonMainframe = false; tray.ShowBalloonTip(6000, "Capri is riding your cursor", hotkey ? "Press " + hopName + " to get her off." : "Right-click her tray icon, then choose Move and Hop off.", ToolTipIcon.Info); }
            Play(perchGlitch);
            frames.Start();
            pill.Hide();
            mainframe.Sync();
        }

        private void StopRide()
        {
            if (hotkey && IsHandleCreated) Native.UnregisterHotKey(Handle, DismountId);
            hotkey = false;
            if (!riding) return;
            riding = false;
            leanAngle = 0;
            Play(grin);
            if (IsHandleCreated) Native.SetWindowLong(Handle, -20, Native.GetWindowLong(Handle, -20) & ~0x20);
            if (rideItem != null) rideItem.Text = "Ride cursor";
            if (tray != null) tray.Text = "Capri · Double-click to restore";
            if (!IsDisposed) { Location = anchor; UpdateAnimation(); SavePreferences(); mainframe.Sync(); }
        }

        // Her pointer starts a job beside her: where she sits, then on the task panel once she's hopped onto it.
        private Point PointerHome()
        {
            if (hidden || !preferences.Motion) return Cursor.Position;
            return new Point(anchor.X + PaddingSize + (int)(preferences.Size * 0.267f) - 12, anchor.Y + PaddingSize + (int)(preferences.Size * 0.73f) + 12);
        }

        // She rides their cursor, never her own pointer, which she'd hide.
        private void FollowCursor()
        {
            Point cursor = Cursor.Position;
            Rectangle area = Screen.FromPoint(cursor).WorkingArea;
            int seatX = PaddingSize + (int)(preferences.Size * 0.267f) - 12;
            int seatY = PaddingSize + (int)(preferences.Size * 0.73f) + 12;
            Point target = Within(new Point(cursor.X - seatX, cursor.Y - seatY), area, PerchedBody);
            int nx = anchor.X + (int)Math.Round((target.X - anchor.X) * 0.25);
            int ny = anchor.Y + (int)Math.Round((target.Y - anchor.Y) * 0.25);
            double velocity = Math.Max(-8, Math.Min(8, (nx - anchor.X) * 0.4));
            leanAngle = leanAngle * 0.8 + velocity * 0.2;
            anchor = Within(new Point(nx, ny), area, PerchedBody);
        }

        private Point Hip()
        {
            if (walking && seat != null) return new Point(anchor.X + PaddingSize + (int)(preferences.Size * (StandX - StandShift)), anchor.Y + PaddingSize + (int)(preferences.Size * StandY));
            return new Point(anchor.X + PaddingSize + (int)(preferences.Size * SitX), anchor.Y + PaddingSize + (int)(preferences.Size * SitY));
        }

        private Point Standing(int x, int y) { return new Point(x - PaddingSize - (int)(preferences.Size * (StandX - StandShift)), y - PaddingSize - (int)(preferences.Size * StandY)); }

        private Ledge Perch(System.Collections.Generic.IEnumerable<Ledge> ledges, Point hip) { return Ledges.Below(ledges, hip, Math.Max(32, (int)(preferences.Size * 0.45f)), Math.Max(160, preferences.Size), 24, Headroom()); }

        private int Headroom() { return (int)Math.Ceiling(preferences.Size * (SitY - PerchedBody.Top)); }

        private Point Seated(int x, int y) { return new Point(x - PaddingSize - (int)(preferences.Size * SitX), y - PaddingSize - (int)(preferences.Size * SitY)); }

        private System.Collections.Generic.List<IntPtr> Skip()
        {
            System.Collections.Generic.List<IntPtr> skip = new System.Collections.Generic.List<IntPtr>();
            foreach (Form own in new Form[] { this, pill, box, typer, mainframe, tear }) if (own.IsHandleCreated) skip.Add(own.Handle);
            return skip;
        }

        private System.Collections.Generic.List<Ledge> Around()
        {
            System.Collections.Generic.List<IntPtr> skip = Skip();
            IntPtr own = mainframe.IsHandleCreated ? mainframe.Handle : IntPtr.Zero;
            skip.Remove(own);
            return Ledges.Find(skip, icons, own);
        }

        private void SpawnInMiddle()
        {
            Rectangle area = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).WorkingArea;
            seat = null;
            anchor = KeepOnScreen(new Point(area.Left + (area.Width - Width) / 2, area.Top + (area.Height - Height) / 2));
            Location = anchor;
            spawnFall = true;
        }

        private void Fall()
        {
            spawnFall = false;
            if (riding || onPanel || dragging || hanging || hidden || seat != null) return;
            falling = true;
            fallTo = null;
            fallSpeed = 0;
            fallStep = clock.Elapsed.TotalSeconds;
            frames.Start();
        }

        private bool Drop()
        {
            if (preferences.NoSitting || onPanel) return false;
            Ledge target = Perch(Around(), Hip());
            if (target == null) return false;
            falling = true;
            fallTo = target;
            fallSpeed = 0;
            fallStep = clock.Elapsed.TotalSeconds;
            frames.Start();
            return true;
        }

        internal string ErrorDetails()
        {
            Cloud remote = brain.Remote;
            string head = "Capri v" + Assembly.GetExecutingAssembly().GetName().Version.ToString(3) + " | brain: " + (remote != null ? remote.Name + " " + remote.Model : brain.Local != null ? "built-in " + brain.Model : brain.Model != null ? "Ollama " + brain.Model : "none") + " | watch: " + (preferences.Watch ? GlanceGap + " s" : "off") + " | voice: " + (voice.Key != null ? "ElevenLabs" : "none") + " | hey capri: " + (preferences.HeyCapri ? "on" : "off");
            string[] lines = new string[0];
            try { if (Brain.LogPath != null && File.Exists(Brain.LogPath)) lines = File.ReadAllLines(Brain.LogPath); } catch (IOException) { }
            int from = Math.Max(0, lines.Length - 25);
            return head + Environment.NewLine + (lines.Length == 0 ? "No errors logged." : string.Join(Environment.NewLine, lines, from, lines.Length - from));
        }

        private void CopyErrors()
        {
            try { Clipboard.SetText(ErrorDetails()); }
            catch (System.Runtime.InteropServices.ExternalException) { return; }
            Tell("copy error details", "Copied my error log. Paste it in the Discord so they can fix me, choom.");
        }

        internal void ToggleWander()
        {
            preferences.Wander = !preferences.Wander;
            wanderItem.Checked = preferences.Wander;
            nextWander = preferences.Wander ? clock.Elapsed.TotalSeconds + 3 : -1;
            SavePreferences();
            mainframe.Sync();
        }

        private void CheckPopIn(double now, long quiet)
        {
            if (popOut >= 0 && (clicks != popClicks || chatting || typer.Visible || talkState != TalkState.Off)) EndPopIn(false);
            if (popOut >= 0 && now >= popOut && speech == null) EndPopIn(true);
            if (!preferences.CheckIns || Hushed) { nextPopIn = -1; return; }
            if (nextPopIn < 0) nextPopIn = now + PopGap();
            if (now < nextPopIn) return;
            nextPopIn = now + PopGap();
            if (quiet > 60000 || quitting || dragging || pressed || chatting || typer.Visible || menu.Visible || speech != null || talkState != TalkState.Off || outro != null || onPanel || popOut >= 0) return;
            PopIn(now);
        }

        private void PopIn(double now)
        {
            bool wasHidden = hidden;
            string line = PopLines[random.Next(PopLines.Length)];
            // With Wander off, or on a spot they picked (Sit here, Hang here, riding the cursor), she says hi from where she is.
            if (!wasHidden && (!preferences.Wander || riding || hanging || (seat != null && seat.Free)))
            {
                if (IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                Say(line);
                popOut = preferences.OnTop ? -1 : clock.Elapsed.TotalSeconds + 6;
                popClicks = clicks;
                popHide = false;
                return;
            }
            Rectangle area = Screen.FromPoint(Cursor.Position).WorkingArea;
            Point spot = new Point(area.Left + (int)(random.NextDouble() * Math.Max(1, area.Width - Width)), area.Bottom - Height - 12);
            Action arrive = delegate
            {
                StopRide();
                seat = null;
                falling = false;
                walking = false;
                anchor = spot;
                ShowHidden(false);
                DropSoon();
                if (IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                Say(line);
                popOut = wasHidden || !preferences.OnTop ? clock.Elapsed.TotalSeconds + 6 : -1;
                popClicks = clicks;
                popHide = wasHidden;
            };
            if (wasHidden) arrive();
            else GlitchOut(arrive, false);
        }

        private bool popHide;

        private void EndPopIn(bool leave)
        {
            popOut = -1;
            if (!preferences.OnTop && IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            if (leave && popHide && !hidden) SetHidden(true);
            popHide = false;
        }

        internal void ToggleCheckIns()
        {
            preferences.CheckIns = !preferences.CheckIns;
            nextPopIn = -1;
            nudgeOut = -1;
            nudgeGap = NudgeGap;
            noticed = -1;
            SavePreferences();
            mainframe.Sync();
        }

        internal bool Shushed { get { return shushed; } }

        // Her quiet key or a nap they asked for: no glances, pop-ins, check-ins, cheers or jokes.
        private bool Hushed { get { return shushed || napAsked || napping; } }

        // Her quiet key, for when they focus or game: she stops what she's saying and talks only when they talk to her.
        // Watch my screen and Check in on me keep their settings and pick up again on the next press.
        internal void ToggleShush()
        {
            shushed = !shushed;
            nextPopIn = -1;
            nudgeOut = -1;
            nudgeGap = NudgeGap;
            noticed = -1;
            nextGlance = -1;
            if (shushed) voice.Stop();
            Say(shushed ? "Going quiet. " + QuietKeyName + " when you want me back." : "I'm back, choom.");
        }

        // With Check in on me on, ignored for a while when they're at the PC, she comes over and asks for attention: a click gets a happy line, silence gets a sulk and a longer wait.
        private void CheckNudge(double now, long quiet)
        {
            bool attending = clicks != noticedClicks || dragging || pressed || chatting || typer.Visible || menu.Visible || talkState != TalkState.Off || onPanel;
            if (noticed < 0 || attending) { noticed = now; noticedClicks = clicks; }
            if (nudgeOut >= 0)
            {
                if (attending)
                {
                    nudgeOut = -1;
                    nudgeGap = NudgeGap;
                    if (!chatting && !typer.Visible && talkState == TalkState.Off && !onPanel) Say(NoticedLines[random.Next(NoticedLines.Length)]);
                }
                else if (now >= nudgeOut && speech == null)
                {
                    nudgeOut = -1;
                    nudgeGap = Math.Min(nudgeGap * 2, NudgeGap * 4);
                    noticed = now;
                    if (quiet < 20000 && !hidden) Say(SnubbedLines[random.Next(SnubbedLines.Length)]);
                }
                return;
            }
            if (!preferences.CheckIns || Hushed || hidden || quiet > 30000 || now - noticed < nudgeGap || (lastGlance >= 0 && now - lastGlance < 300)) return;
            if (quitting || riding || onPanel || falling || hanging || typer.Visible || speech != null || outro != null || popOut >= 0 || (clip != idle && clip != perch)) return;
            Nudge(now);
        }

        private void Nudge(double now)
        {
            nudgeOut = now + 20;
            string line = NudgeLines[random.Next(NudgeLines.Length)];
            Point cursor = Cursor.Position;
            Point hip = Hip();
            Rectangle area = Screen.FromPoint(cursor).WorkingArea;
            Action ask = delegate
            {
                // Behind other windows she can't be noticed, so she comes to the front until it's over, the way a pop-in does.
                if (!preferences.OnTop && IsHandleCreated)
                {
                    Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                    popOut = clock.Elapsed.TotalSeconds + 20;
                    popClicks = clicks;
                    popHide = false;
                }
                Say(line);
            };
            // With Wander off, or on a Sit here spot, she asks from where she is.
            if (!preferences.Wander || (seat != null && seat.Free) || (area.Contains(hip) && Math.Abs(hip.X - cursor.X) <= Math.Max(300, Width * 2))) { ask(); return; }
            int x = cursor.X - area.Left < area.Width / 2 ? cursor.X + Width / 2 : cursor.X - Width - Width / 2;
            Point spot = new Point(Math.Max(area.Left, Math.Min(area.Right - Width, x)), area.Bottom - Height - 12);
            GlitchOut(delegate
            {
                StopRide();
                seat = null;
                falling = false;
                walking = false;
                anchor = spot;
                ShowHidden(false);
                DropSoon();
                ask();
            }, false);
        }

        private static bool Installed()
        {
            try { return string.Equals(Path.GetFullPath(Application.ExecutablePath), Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Capri", "Capri.exe")), StringComparison.OrdinalIgnoreCase); }
            catch (ArgumentException) { return false; }
            catch (NotSupportedException) { return false; }
            catch (IOException) { return false; }
        }

        // She starts with Windows by default: the installed copy turns it on once, and turning it off sticks.
        internal void DefaultStartup(bool installed)
        {
            if (preferences.StartupSet || !installed || !Startup.Set(Application.ExecutablePath, true)) return;
            preferences.StartupSet = true;
            SavePreferences();
            mainframe.Sync();
        }

        internal bool StartsWithWindows { get { return Startup.On(Application.ExecutablePath); } }

        internal void ToggleStartup()
        {
            if (Portable.Current != null) { Brain.Log("startup", -1, "She runs from a USB drive, so she doesn't add herself to this PC's Windows startup."); return; }
            if (!Startup.Set(Application.ExecutablePath, !StartsWithWindows)) Brain.Log("startup", -1, "Windows wouldn't let Capri change her Run entry.");
            preferences.StartupSet = true;
            SavePreferences();
            mainframe.Sync();
        }


        internal bool UsesCursor { get { return !preferences.QuickHands; } }

        internal void ToggleCursor()
        {
            preferences.QuickHands = !preferences.QuickHands;
            SavePreferences();
            mainframe.Sync();
        }

        // Blackwall mode is SECURITY's Blackwall preset now. Flipping it the old way picks Blackwall, or Trusted to go back.
        internal bool Bypassing { get { return Computer.Bypass; } }

        internal void ToggleBypass() { Security.Pick(Computer.Bypass ? Security.Trusted : Security.Blackwall); }

        // Settings from before the SECURITY window have no toggles: Blackwall mode moves to the Blackwall preset, "Hey Capri"
        // and all, and everyone else gets Trusted, which is how she worked without it. True when it moved them.
        internal static bool Migrate(Preferences saved)
        {
            if (saved.Permissions != null) return false;
            saved.Permissions = Security.Of(saved.Bypass ? Security.Blackwall : Security.Trusted);
            if (saved.Bypass) saved.HeyCapri = true;
            return true;
        }

        // A toggle or preset changed: it's saved, Blackwall mode's old flag follows toggles 8 to 10 for older versions, and
        // Settings and her SECURITY window show it.
        private void SecurityChanged()
        {
            preferences.Permissions = Security.Saved;
            preferences.Bypass = Computer.Bypass;
            SavePreferences();
            mainframe.Sync();
        }

        // The smoke test's SECURITY checks: each preset's toggles, Custom after a flip, settings from before it, every gate
        // asking when its toggle is off and running on a yes (in text and voice chat, before a brain and in her jobs),
        // passwords staying theirs to type, her prompts following the toggles, and the window at 100%, 150% and 200%.
        private void SecurityChecks(System.Collections.Generic.List<string> checks, string output)
        {
            Func<string> bits = delegate { System.Text.StringBuilder all = new System.Text.StringBuilder(); for (int i = 0; i < Security.Count; i++) all.Append(Security.On(i) ? '1' : '0'); return all.ToString(); };
            string[] presetBits = { "00000000000", "11100000000", "11111110000", "11111111111" };
            System.Collections.Generic.List<string> wrong = new System.Collections.Generic.List<string>();
            for (int preset = Security.Lockdown; preset <= Security.Blackwall; preset++)
            {
                Security.Pick(preset);
                string shown = bits();
                if (shown != presetBits[preset] || Security.Preset != preset || HeyCapriOn != (preset == Security.Blackwall) || preferences.Permissions != presetBits[preset].Substring(0, 10) || preferences.Bypass != (preset == Security.Blackwall) || Computer.Bypass != (preset == Security.Blackwall))
                    wrong.Add(Security.Presets[preset] + " " + shown + " saved " + preferences.Permissions + " hey " + HeyCapriOn);
            }
            Security.Pick(Security.Trusted);
            Security.Set(Security.Open, false);
            string customShown = mainframe.JobsStatus + " / " + Security.Saved;
            bool custom = Security.Preset == Security.Custom && preferences.Permissions == "0111111000" && customShown == "cursor | Security: Custom / 0111111000";
            Security.Set(Security.Open, true);
            bool backToTrusted = Security.Preset == Security.Trusted && preferences.Permissions == "1111111000" && !HeyCapriOn;
            if (wrong.Count > 0 || !custom || !backToTrusted) throw new Exception("SECURITY's presets went wrong: " + string.Join(" / ", wrong.ToArray()) + " / custom " + customShown + " / back " + backToTrusted);
            checks.Add("PASS SECURITY presets: Lockdown turns every toggle off, Guarded the first three on, Trusted the first seven (the default) and Blackwall all eleven, \"Hey Capri\" included; flipping one makes it Custom, flipping it back is Trusted again, and each is saved");

            DataContractJsonSerializer json = new DataContractJsonSerializer(typeof(Preferences));
            Func<string, Preferences> older = delegate(string text) { return (Preferences)json.ReadObject(new MemoryStream(System.Text.Encoding.UTF8.GetBytes(text))); };
            Preferences wasBlackwall = older("{\"Bypass\":true,\"Size\":240}"), wasDefault = older("{\"Size\":240}"), wasMixed = older("{\"Bypass\":true,\"Permissions\":\"1010000000\",\"Size\":240}");
            bool movedBlackwall = Migrate(wasBlackwall) && wasBlackwall.Permissions == "1111111111" && wasBlackwall.HeyCapri;
            bool movedDefault = Migrate(wasDefault) && wasDefault.Permissions == "1111111000" && !wasDefault.HeyCapri;
            bool keptMixed = !Migrate(wasMixed) && wasMixed.Permissions == "1010000000" && !Migrate(wasBlackwall);
            Security.Load(wasBlackwall.Permissions);
            bool loadedBlackwall = Computer.Bypass && Security.On(Security.Mouse);
            Security.Load(wasMixed.Permissions);
            bool loadedMixed = Security.On(Security.Open) && !Security.On(Security.Media) && Security.On(Security.Shortcuts) && !Security.On(Security.Sends) && Security.Preset == Security.Custom;
            Security.Load("not toggles");
            bool unreadable = Security.Preset == Security.Trusted;
            Security.Load(preferences.Permissions);
            if (!movedBlackwall || !movedDefault || !keptMixed || !loadedBlackwall || !loadedMixed || !unreadable || Security.Preset != Security.Trusted) throw new Exception("SECURITY didn't take over from Blackwall mode's settings: " + movedBlackwall + " " + movedDefault + " " + keptMixed + " " + loadedBlackwall + " " + loadedMixed + " " + unreadable);
            checks.Add("PASS SECURITY from older settings: Blackwall mode (Bypass) moves to the Blackwall preset with \"Hey Capri\" on, everyone else gets Trusted, saved toggles load as they are, and unreadable ones fall back to Trusted");

            // Her own tools: each toggle off holds its call and she asks; a yes runs it once, a no leaves it and anything else drops it.
            System.Collections.Generic.List<string> did = new System.Collections.Generic.List<string>();
            Action<string> runWas = Hands.Run;
            Action<byte> pressWas = Hands.Press;
            Action<byte[]> chordWas = Hands.Chord;
            Func<System.Collections.Generic.List<InstalledApp>> catalogWas = Hands.Catalog;
            Func<System.Collections.Generic.List<OpenWindow>> windowsWas = Hands.Windows;
            Func<OpenWindow, string, bool> steerWas = Hands.Steer;
            Func<string, int, bool> powerWas = Hands.Power;
            Func<string, string, string> workWas = Hands.Work;
            Func<Sight> lookWas = Computer.Look;
            Func<IntPtr> frontWas = Computer.Front;
            Func<string, ToolArguments, Sight, string> actWas = Computer.Act;
            Func<bool> secretWas = Computer.SecretFocus;
            bool quickWas = preferences.QuickHands;
            string modelWas = brain.Model;
            string[] tools = { "open_app", "media", "shortcut", "app_window", "power", "use_computer" };
            string[] questions = { "Open spotify? Say yes and I will.", "Turn the volume up? Say yes and I will.", "Take a screenshot? Say yes and I will.", "Switch to discord? Say yes and I will.", "Lock your PC? Say yes and I will.", "Use your mouse and keyboard to message Sam hi on Discord? Say yes and I will." };
            string[] ranWanted = { "run spotify-id", "key AF", "chord ", "steer switch_to Discord", "power lock", "job message Sam hi on Discord" };
            ToolArguments[] calls = { new ToolArguments { Name = "spotify" }, new ToolArguments { Action = "volume_up" }, new ToolArguments { Name = "screenshot" }, new ToolArguments { Name = "discord", Action = "switch_to" }, new ToolArguments { Action = "lock" }, new ToolArguments { Task = "message Sam hi on Discord" } };
            System.Collections.Generic.List<string> gates = new System.Collections.Generic.List<string>(), voiceTold = new System.Collections.Generic.List<string>();
            string declined, dropped, mixedAsk, mixedRan, voiceHeld, voiceRan, quickKey, cursorKey, noBrain, lockdownFree, textChat;
            try
            {
                Hands.Run = delegate(string id) { lock (did) did.Add("run " + id); };
                Hands.Press = delegate(byte key) { lock (did) did.Add("key " + key.ToString("X2")); };
                Hands.Chord = delegate(byte[] keys) { lock (did) did.Add("chord " + keys.Length); };
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Spotify", "spotify-id") }; };
                Hands.Forget();
                OpenWindow discord = new OpenWindow(new IntPtr(9), "#general | Discord", "Discord");
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow> { discord }; };
                Hands.Steer = delegate(OpenWindow window, string action) { lock (did) did.Add("steer " + action + " " + window.Program); return true; };
                Hands.Power = delegate(string action, int seconds) { lock (did) did.Add("power " + action); return true; };
                Hands.Work = delegate(string job, string asked) { lock (did) did.Add("job " + job); return "Did it."; };
                preferences.QuickHands = true;
                for (int i = 0; i <= Security.Mouse; i++)
                {
                    Security.Pick(Security.Trusted);
                    Security.Set(i, false);
                    did.Clear();
                    string held = DoTool(tools[i], calls[i]);
                    string early = string.Join(",", did.ToArray()), question = Security.Question;
                    string yes = ResumeJob("yes");
                    string after = string.Join(",", did.ToArray());
                    if (!Security.IsHold(held) || early.Length > 0 || question != questions[i] || yes == null || Security.IsHold(yes) || after.IndexOf(ranWanted[i], StringComparison.Ordinal) < 0 || Security.Holding != null)
                        gates.Add(Security.Names[i] + ": " + held + " / ran early " + early + " / asked " + question + " / yes " + yes + " / ran " + after);
                }
                Security.Pick(Security.Trusted);
                Security.Set(Security.Open, false);
                did.Clear();
                DoTool("open_app", calls[0]);
                declined = ResumeJob("nah") + " [" + string.Join(",", did.ToArray()) + "]";
                DoTool("open_app", calls[0]);
                dropped = (ResumeJob("what's the weather like?") ?? "null") + " / " + (Security.Holding ?? "nothing held") + " [" + string.Join(",", did.ToArray()) + "]";
                // Two held and one that ran: what ran, then one question for both, and one yes runs both.
                Security.Pick(Security.Trusted);
                Security.Set(Security.Media, false);
                Security.Set(Security.Power, false);
                did.Clear();
                System.Collections.Generic.List<string> results = new System.Collections.Generic.List<string> { DoTool("open_app", calls[0]), DoTool("media", calls[1]), DoTool("power", calls[4]) };
                mixedAsk = Security.Reply(results);
                mixedRan = ResumeJob("yeah") + " [" + string.Join(",", did.ToArray()) + "]";
                // Looking, notes, her own nap, moves and animations, what's playing and cancelling a shutdown never ask, even in Lockdown.
                Security.Pick(Security.Lockdown);
                did.Clear();
                string playing = DoTool("media", new ToolArguments { Action = "now_playing" }), cancel = DoTool("power", new ToolArguments { Action = "cancel" });
                lockdownFree = (Security.IsHold(playing) || Security.IsHold(cancel) ? "held " + playing + " / " + cancel : "free") + " | " + Security.Needs("look_at_screen", null) + Security.Needs("remember", null) + Security.Needs("nap", null) + Security.Needs("move_yourself", null) + Security.Needs("animate", null);
                // Before she has a brain her question shows on its own, and their yes works without one.
                Security.Pick(Security.Trusted);
                Security.Set(Security.Media, false);
                did.Clear();
                noBrain = Security.Said(DoTool("media", calls[1])) + " -> " + Security.Resume("ok", DoTool) + " [" + string.Join(",", did.ToArray()) + "]";
                // Text chat: her question goes out word for word with no second brain call, and their next message's yes does it.
                Security.Pick(Security.Trusted);
                Security.Set(Security.Media, false);
                did.Clear();
                Brain talker = new Brain();
                talker.Model = "smoke-test-model";
                talker.Act = delegate(string talkTool, ToolArguments talkArgs) { return DoTool(talkTool, talkArgs); };
                string talkAsked = talker.Ask("turn the volume up"), talkEarly = string.Join(",", did.ToArray());
                textChat = talkAsked + " / " + talkEarly + " / " + talker.Ask("yes") + " [" + string.Join(",", did.ToArray()) + "]";
                // Use your mouse and keyboard for jobs off keeps her quick tools quick, so a YouTube search doesn't take the mouse.
                brain.Model = "smoke-test-model";
                preferences.QuickHands = false;
                Security.Pick(Security.Trusted);
                cursorKey = MouseKey("open_website", new ToolArguments { Site = "youtube", Search = "lofi" }) ?? "null";
                Security.Set(Security.Mouse, false);
                quickKey = MouseKey("open_website", new ToolArguments { Site = "youtube", Search = "lofi" }) ?? "null";
                // Voice chat: a held job is asked about at once instead of starting on the mouse, and their spoken yes runs it.
                did.Clear();
                finishedTest = delegate(string line) { lock (voiceTold) voiceTold.Add(line); };
                voiceHeld = AgentAct(null, "use_computer", calls[5]) + " [" + string.Join(",", did.ToArray()) + "]";
                bool answered = VoiceAnswer("yes", asking, null);
                Stopwatch voiceWait = Stopwatch.StartNew();
                while (voiceWait.ElapsedMilliseconds < 5000) { lock (voiceTold) if (voiceTold.Count > 0) break; Thread.Sleep(20); }
                lock (voiceTold) lock (did) voiceRan = answered + " / " + string.Join(" | ", voiceTold.ToArray()) + " [" + string.Join(",", did.ToArray()) + "]";
            }
            finally
            {
                Hands.Run = runWas;
                Hands.Press = pressWas;
                Hands.Chord = chordWas;
                Hands.Catalog = catalogWas;
                Hands.Forget();
                Hands.Windows = windowsWas;
                Hands.Steer = steerWas;
                Hands.Power = powerWas;
                Hands.Work = workWas;
                preferences.QuickHands = quickWas;
                brain.Model = modelWas;
                finishedTest = null;
                lock (shortcutGate) { shortcutTool = null; shortcutResult = null; }
                Security.Drop();
                Security.Pick(Security.Trusted);
            }
            if (gates.Count > 0) throw new Exception("A SECURITY toggle didn't ask first or run on a yes: " + string.Join(" // ", gates.ToArray()));
            if (declined != Security.Left + " []" || dropped != "null / nothing held []") throw new Exception("A no or a new message after her SECURITY question went wrong: " + declined + " / " + dropped);
            if (mixedAsk != "Opened Spotify. Turn the volume up and lock your PC? Say yes and I will." || mixedRan.IndexOf("key AF", StringComparison.Ordinal) < 0 || mixedRan.IndexOf("power lock", StringComparison.Ordinal) < 0) throw new Exception("Two held calls weren't one question and one yes: " + mixedAsk + " / " + mixedRan);
            if (lockdownFree != "free | -1-1-1-1-1") throw new Exception("Lockdown asked about something that never asks: " + lockdownFree);
            if (!noBrain.StartsWith("Turn the volume up? Say yes and I will. -> Turned the volume up", StringComparison.Ordinal) || noBrain.IndexOf("key AF", StringComparison.Ordinal) < 0) throw new Exception("Asking first before she has a brain went wrong: " + noBrain);
            if (!textChat.StartsWith("Turn the volume up? Say yes and I will. /  / Turned the volume up.", StringComparison.Ordinal) || textChat.IndexOf("key AF", StringComparison.Ordinal) < 0) throw new Exception("Text chat didn't ask first or run on a yes: " + textChat);
            if (cursorKey == "null" || quickKey != "null") throw new Exception("Use your mouse and keyboard for jobs off still put a quick tool on the mouse: " + cursorKey + " / " + quickKey);
            if (!voiceHeld.StartsWith(Security.Hold + "\"Use your mouse and keyboard to message Sam hi on Discord? Say yes and I will.\"", StringComparison.Ordinal) || !voiceHeld.EndsWith("[]", StringComparison.Ordinal) || !voiceRan.StartsWith("True / Capri's hands did what they just said yes to (use_computer): Did it.", StringComparison.Ordinal) || voiceRan.IndexOf("job message Sam hi on Discord", StringComparison.Ordinal) < 0)
                throw new Exception("Voice chat didn't ask first or run on a spoken yes: " + voiceHeld + " / " + voiceRan);
            checks.Add("PASS SECURITY gates on her tools: with each of the first six toggles off she holds the call and asks (\"Open spotify? Say yes and I will.\", \"Lock your PC?\", \"Use your mouse and keyboard to message Sam hi on Discord?\"), nothing runs until a yes, a yes runs it once, a no leaves it alone and a new message drops it; two held calls are one question and one yes; looking, notes, her nap, moves, animations, what's playing and cancelling a shutdown never ask; it works in text chat (her question word for word, with no second brain call), before she has a brain and in voice chat; and with Use your mouse and keyboard off her quick tools stay off the mouse");

            // Her prompts follow the toggles, so she calls the tool and lets Capri ask instead of asking or saying it's done.
            string trustedNote = Security.Note, trustedAsk = Computer.AskLine(), trustedPrompt = Computer.Allowing(Computer.Prompt), trustedHands = Hands.Prompt;
            Security.Set(Security.Open, false);
            string openNote = Hands.Note, openHands = Hands.Prompt;
            Security.Pick(Security.Blackwall);
            string blackwallNote = Security.Note, blackwallAsk = Computer.AskLine(), blackwallPrompt = Computer.Allowing(Computer.Prompt);
            Security.Pick(Security.Trusted);
            Security.Set(Security.Pays, true);
            string paysAsk = Computer.AskLine(), paysPrompt = Computer.Allowing(Computer.Prompt), paysTools = Computer.Tools;
            Security.Pick(Security.Trusted);
            Security.Set(Security.Secrets, true);
            string secretsPrompt = Computer.Allowing(Computer.Prompt);
            Security.Pick(Security.Trusted);
            const string openLine = "They've set her SECURITY settings to ask first before you open apps, games or sites. Still call the tool as soon as they ask: Capri asks them herself";
            if (trustedNote.Length > 0 || trustedPrompt != Computer.Prompt || trustedHands != Hands.Prompt || trustedHands.IndexOf("SECURITY", StringComparison.Ordinal) >= 0 || trustedAsk.IndexOf("Ask them only before a step that buys or pays", StringComparison.Ordinal) != 0 || openNote.IndexOf(openLine, StringComparison.Ordinal) < 0 || openHands.IndexOf("Call the tool.\n" + openLine, StringComparison.Ordinal) < 0
                || blackwallNote.Length > 0 || blackwallAsk.IndexOf("never ask before buying", StringComparison.Ordinal) < 0 || blackwallPrompt.IndexOf("Bypass all permissions", StringComparison.Ordinal) < 0
                || paysAsk.IndexOf("buys or pays", StringComparison.Ordinal) >= 0 || paysAsk.IndexOf("They've said yes ahead of time to buying, paying and booking", StringComparison.Ordinal) < 0 || paysTools.IndexOf("buying, paying and booking", StringComparison.Ordinal) < 0 || paysPrompt.IndexOf("call ask before you buy", StringComparison.Ordinal) >= 0 || paysPrompt.IndexOf("Only call ask before a send, post, delete or install their job didn't mention", StringComparison.Ordinal) < 0 || paysPrompt.IndexOf("Never type passwords", StringComparison.Ordinal) < 0
                || secretsPrompt.IndexOf("Type passwords, card numbers and other private details whenever their job needs them.", StringComparison.Ordinal) < 0 || secretsPrompt.IndexOf("Always call ask before you buy or pay for anything.", StringComparison.Ordinal) < 0)
                throw new Exception("Her prompts didn't follow SECURITY: " + trustedNote + " / " + openNote.Substring(Math.Max(0, openNote.Length - 300)) + " / " + paysAsk);
            checks.Add("PASS SECURITY prompts: under Trusted and Blackwall her prompts and tools read as they did; with a tool's toggle off her brain is told to still call it and let Capri ask; and her jobs' ask tool and prompt follow Pay, buy and book, Things your request didn't mention and Type passwords and card numbers one by one");

            // Her jobs: toggles 7 to 10, with a pretend chat box and a pretend sign-in page.
            System.Collections.Generic.List<string> acted = new System.Collections.Generic.List<string>();
            Sight chat = new Sight { Window = new IntPtr(7), Title = "#general | Discord", Program = "Discord" };
            chat.Targets.Add(new Target { Number = 1, Role = "box", Name = "Message #general", Line = true, Box = new Rectangle(10, 10, 200, 20) });
            Sight login = new Sight { Window = new IntPtr(7), Title = "Sign in", Program = "game" };
            login.Targets.Add(new Target { Number = 1, Role = "box", Name = "Password", Secret = true, Line = true, Box = new Rectangle(10, 10, 200, 20) });
            Sight showing = chat;
            Func<string[], string, Job> scripted = delegate(string[] script, string task)
            {
                int line = 0;
                Job made = new Job(task);
                made.Think = delegate(string system, string user, System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> made2) { return script[Math.Min(line++, script.Length - 1)]; };
                return made;
            };
            string[] sendScript = { "type{\"target\": \"1\", \"text\": \"hi\", \"enter\": \"yes\"}", "done{\"text\": \"Sent hi.\"}" };
            string[] keyScript = { "press{\"keys\": \"win+r\"}", "done{\"text\": \"Opened the Run box.\"}" };
            string[] passwordScript = { "ask{\"text\": \"What's your password?\"}" };
            string sendTrusted, sendAsked, sendYes, keyAsked, keyYes, keyBlackwall, passwordTrusted, passwordOn;
            bool keysFreed, needsRight;
            try
            {
                Computer.Look = delegate { return showing; };
                Computer.Front = delegate { return new IntPtr(7); };
                Computer.SecretFocus = delegate { return false; };
                Computer.Act = delegate(string name, ToolArguments a, Sight s) { lock (acted) acted.Add(name + " " + (a.Text ?? a.Keys)); return name == "type" ? "Typed it." : "Did it."; };
                Security.Pick(Security.Trusted);
                sendTrusted = scripted(sendScript, "message Sam hi on Discord").Run() + " [" + string.Join(",", acted.ToArray()) + "]";
                acted.Clear();
                Security.Set(Security.Sends, false);
                Job send = scripted(sendScript, "message Sam hi on Discord");
                sendAsked = send.Run() + " [" + string.Join(",", acted.ToArray()) + "] " + send.Asking;
                sendYes = send.Run() + " [" + string.Join(",", acted.ToArray()) + "]";
                acted.Clear();
                Security.Pick(Security.Trusted);
                Job keys = scripted(keyScript, "open the run box");
                keyAsked = keys.Run() + " [" + string.Join(",", acted.ToArray()) + "] " + keys.Asking;
                keyYes = keys.Run() + " [" + string.Join(",", acted.ToArray()) + "]";
                keysFreed = !Computer.Barred("win+r");
                acted.Clear();
                Security.Pick(Security.Blackwall);
                keyBlackwall = scripted(keyScript, "open the run box").Run() + " [" + string.Join(",", acted.ToArray()) + "]";
                acted.Clear();
                showing = login;
                Security.Pick(Security.Trusted);
                passwordTrusted = scripted(passwordScript, "log me in to my game").Run();
                Security.Set(Security.Secrets, true);
                passwordOn = scripted(passwordScript, "log me in to my game").Run();
                // What each kind of step needs: an asked-for send needs toggle 7, buying 8, and anything unmentioned 9 as well.
                Security.Pick(Security.Trusted);
                Job sam = new Job("message Sam hi on Discord"), hoodie = new Job("buy the blue hoodie"), browse = new Job("search the shop for hoodies");
                bool trusted = !sam.Needs("send") && sam.Needs("delete") && hoodie.Needs("buy") && browse.Needs("buy") && sam.Needs("keys") && Computer.Barred("win+r") && Computer.Risk("press", new ToolArguments { Keys = "win+r" }, chat) == "keys";
                Security.Set(Security.Pays, true);
                bool pays = !hoodie.Needs("buy") && browse.Needs("buy");
                Security.Set(Security.Unasked, true);
                bool unasked = !browse.Needs("buy") && !sam.Needs("delete") && !sam.Needs("keys") && !Computer.Barred("win+r");
                Security.Set(Security.Sends, false);
                bool sends = sam.Needs("send") && sam.Needs("delete") && !hoodie.Needs("buy");
                Security.Pick(Security.Lockdown);
                bool lockdown = sam.Needs("send") && hoodie.Needs("buy") && sam.Needs("keys");
                needsRight = trusted && pays && unasked && sends && lockdown;
                if (!needsRight) wrong.Add("needs: trusted " + trusted + ", pays " + pays + ", unasked " + unasked + ", sends " + sends + ", lockdown " + lockdown);
            }
            finally
            {
                Computer.Look = lookWas;
                Computer.Front = frontWas;
                Computer.Act = actWas;
                Computer.SecretFocus = secretWas;
                Computer.KeysOk = false;
                Security.Pick(Security.Trusted);
            }
            if (sendTrusted != "Sent hi. [type hi]" || sendAsked != "Should I send \"hi\"? [] True" || sendYes != "Sent hi. [type hi]") throw new Exception("Send, post and delete what you asked for went wrong: " + sendTrusted + " / " + sendAsked + " / " + sendYes);
            if (keyAsked != "Should I press win+r? [] True" || keyYes != "Opened the Run box. [press win+r]" || !keysFreed || keyBlackwall != "Opened the Run box. [press win+r]") throw new Exception("Win + R didn't ask first under Things your request didn't mention: " + keyAsked + " / " + keyYes + " / " + keysFreed + " / " + keyBlackwall);
            if (passwordTrusted != Computer.SignInYourself || passwordOn != "What's your password?") throw new Exception("Passwords didn't stay theirs to type: " + passwordTrusted + " / " + passwordOn);
            if (!needsRight) throw new Exception("SECURITY's job toggles went wrong: " + string.Join(" / ", wrong.ToArray()));
            checks.Add("PASS SECURITY in her jobs: Trusted sends what the job asked for and asks before paying, Win + R or anything unmentioned, as before; with Send, post and delete off she asks \"Should I send \"hi\"?\" and sends it on a yes; Win + R asks first and runs on a yes, and Blackwall presses it straight away; Pay, buy and book covers buying the job asked for, and Things your request didn't mention the rest; with Type passwords and card numbers off a sign-in still gets \"You'll need to sign in yourself first.\"");

            // The window: from HABITS, the slider and toggles as they'd use them, and the layout at 100%, 150% and 200%.
            mainframe.ShowSecurity();
            string opened = mainframe.SecurityShown;
            mainframe.FlipSecurity(Security.Open);
            string flipped = mainframe.SecurityShown, flippedSaved = preferences.Permissions;
            mainframe.TapSecurity(Security.Trusted);
            string tapped = mainframe.SecurityShown;
            mainframe.SlideSecurity(Security.Lockdown);
            string locked = mainframe.SecurityShown;
            mainframe.SlideSecurity(Security.Blackwall);
            string walled = mainframe.SecurityShown;
            bool walledHey = HeyCapriOn, walledSettings = mainframe.BlackwallStatus == "Security: Blackwall | She never asks, and listens for Hey Capri.";
            mainframe.SlideSecurity(Security.Trusted);
            string crowded = mainframe.SecurityCrowded;
            mainframe.CloseSecurity();
            float machine = mainframe.Px(1000) / 1000f;
            string at100 = mainframe.SecurityAt(1f / machine, Path.Combine(output, "security-100.png"));
            string at150 = mainframe.SecurityAt(1.5f / machine, Path.Combine(output, "security-150.png"));
            string at200 = mainframe.SecurityAt(2f / machine, Path.Combine(output, "security-200.png"));
            Security.Pick(Security.Trusted);
            if (opened == null || !opened.StartsWith("Trusted | Trusted | 11111110000 | She does what you ask", StringComparison.Ordinal) || !flipped.StartsWith("Custom | Trusted | 01111110000 | Your own mix", StringComparison.Ordinal) || flippedSaved != "0111111000"
                || !tapped.StartsWith("Trusted | Trusted | 11111110000", StringComparison.Ordinal) || !locked.StartsWith("Lockdown | Lockdown | 00000000000 | Everything is off", StringComparison.Ordinal) || !walled.StartsWith("Blackwall | Blackwall | 11111111111 | Everything is on", StringComparison.Ordinal) || !walledHey || !walledSettings || HeyCapriOn)
                throw new Exception("The SECURITY window went wrong: " + opened + " // " + flipped + " // " + tapped + " // " + locked + " // " + walled + " // " + walledSettings);
            if (crowded != null || at100 != null || at150 != null || at200 != null) throw new Exception("The SECURITY window's layout doesn't fit: " + crowded + " / 100% " + at100 + " / 150% " + at150 + " / 200% " + at200);
            checks.Add("PASS SECURITY window: Settings > HABITS opens it on Trusted; a toggle click makes it Custom and saves, a click on the slider puts Trusted back, sliding to Lockdown or Blackwall sets every toggle (and \"Hey Capri\") and Settings follows; at 100%, 150% and 200% nothing overlaps, pokes out or gets cut off (security-100.png, security-150.png, security-200.png)");
        }

        // The smoke test's voice layer checks (Lachy, 29 Oct): the shared ones of the sound itself, her ElevenLabs replies and
        // voice chat getting them, the settings saving and loading, and her VOICE LAYERS window from Settings > VOICE.
        private void LayersChecks(System.Collections.Generic.List<string> checks, string output, short[] tone, Action<string> snap)
        {
            string found, wrong = VoiceFx.LayersCheck(out found);
            if (wrong != null) throw new Exception("Her voice layers went wrong: " + wrong + " (" + found + ")");
            checks.Add("PASS voice layers' sound: off leaves every voice byte for byte as it was, whatever the layers are set to; on, Layer 1 and Layer 2 are copies of her pitched without changing their length, each mixed in 8 dB under her at its own delay: " + found + "; streamed in chunks of any size they come out the same as whole, the delayed tails ring out past her last word and her mouth moves with them, and the limiter holds a 1.8x full-scale stack under clipping");

            // ElevenLabs replies and voice chat: the copies go on, and voice chat's tails come out once the stream goes quiet.
            VoiceFx.Layering was = VoiceFx.Layers, layers = VoiceFx.Layering.Off.Turned(true);
            byte[] toneWav = Voice.Wave(tone, 24000);
            Func<string, byte[]> eleven = delegate(string words) { return toneWav; };
            string problem;
            int rate;
            short[] replied;
            System.Collections.Generic.List<short> chatHeard = new System.Collections.Generic.List<short>();
            int rateWas = chatRate;
            short[] chatSaid = new short[16000 * 2];
            for (int i = 0; i < chatSaid.Length; i++) chatSaid[i] = (short)(7000 * Math.Sin(2 * Math.PI * 190 * i / 16000.0));
            bool chatArmed;
            try
            {
                VoiceFx.Layers = layers;
                replied = Voice.Samples(Voiced(eleven, null, "Hey choom.", out problem), out rate);
                chatRate = 16000;
                for (int at = 0; at < chatSaid.Length; at += 320)
                {
                    short[] piece = new short[320];
                    Array.Copy(chatSaid, at, piece, 0, 320);
                    chatHeard.AddRange(ChatVoice(piece));
                }
                chatArmed = chatTail.Enabled && chatFx != null && chatFx.Layers.Same(layers);
                chatHeard.AddRange(chatFx.Flush());
                Hush();
            }
            finally
            {
                VoiceFx.Layers = was;
                chatRate = rateWas;
            }
            short[] chatWhole = new VoiceFx.Live(16000, 0, 100, 0, 0, 1, true, layers).All(chatSaid);
            bool chatSame = chatHeard.Count == chatWhole.Length;
            for (int i = 0; chatSame && i < chatWhole.Length; i++) chatSame = chatHeard[i] == chatWhole[i];
            if (problem != null || rate != 24000 || replied.Length != tone.Length + 600 || !chatArmed || !chatSame || chatHeard.Count != chatSaid.Length + 400 || chatFx != null || chatTail.Enabled)
                throw new Exception("Her layers didn't go on ElevenLabs: reply " + replied.Length + " samples from " + tone.Length + " (" + problem + "), voice chat armed " + chatArmed + ", " + chatHeard.Count + " samples from " + chatSaid.Length + ", same as whole " + chatSame);
            checks.Add("PASS voice layers on ElevenLabs: a reply gets both copies and comes back 25 ms longer for their tails, and voice chat layers her a chunk at a time, the same as layering the whole line, with the tails let out once the stream goes quiet");

            // The settings: off out of the box and in settings from before them, which get the defaults; each layer saves and loads
            // as set, and out-of-range values come back in range.
            DataContractJsonSerializer json = new DataContractJsonSerializer(typeof(Preferences));
            Preferences old = (Preferences)json.ReadObject(new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{\"Volume\":80,\"VoicePitch\":2}")));
            SetVoiceLayers(new VoiceFx.Layering(true, 3.5, 40, -4.5, 90));
            Preferences loaded;
            using (MemoryStream saved = new MemoryStream())
            {
                json.WriteObject(saved, preferences);
                saved.Position = 0;
                loaded = (Preferences)json.ReadObject(saved);
            }
            SetVoiceLayers(was);
            string loadedShown = LayersOf(loaded).Shown, oldShown = LayersOf(old).Shown, freshShown = LayersOf(new Preferences()).Shown, clamped = new VoiceFx.Layering(true, 40, 900, -0.26, -5).Shown;
            const string plain = "Off | +2, 25 ms | -2.5, 25 ms";
            if (loadedShown != "On | +3.5, 40 ms | -4.5, 90 ms" || oldShown != plain || freshShown != plain || VoiceFx.Layering.Off.Shown != plain || clamped != "On | +12, 250 ms | -0.5, 0 ms" || VoiceFx.Layers.Shown != was.Shown)
                throw new Exception("Her layers' settings went wrong: saved " + loadedShown + ", from before them " + oldShown + ", new " + freshShown + ", clamped " + clamped);
            checks.Add("PASS voice layers' settings: off in blank settings and in settings from before them, with Layer 1 at +2 and Layer 2 at -2.5 semitones, both 25 ms behind her; each layer's pitch and delay save and load as set, in half steps from -12 to +12 semitones and 0 to 250 ms");

            // Her tuned voice (Lachy, 30 Oct): a new install starts with it; settings from before it get it once while every voice
            // slider is where it started, Layer 1's old +1.5 included; anyone who moved one, or already has it, keeps theirs.
            Func<string, Preferences> tunedRead = delegate(string text)
            {
                Preferences read = (Preferences)json.ReadObject(new MemoryStream(System.Text.Encoding.UTF8.GetBytes(text)));
                read.TuneOnce();
                return read;
            };
            Func<Preferences, string> tunedShown = delegate(Preferences p) { return p.Volume + " | " + p.VoicePitch + " | " + p.VoiceSpeed + " | " + p.VoiceRobot + "/" + p.VoiceGlitch + " | HD " + p.HdRobot + "/" + p.HdVoiceGlitch + " | " + LayersOf(p).Shown + " | " + p.VoiceTuned; };
            const string tunedWanted = "80 | 3 | 120 | 0/0 | HD 0/0 | On | +2, 25 ms | -2.5, 25 ms | True";
            string tunedNew = tunedShown(Preferences.Fresh());
            string tunedOld = tunedShown(tunedRead("{\"Volume\":100,\"VoicePitch\":0,\"VoiceSpeed\":100,\"VoiceRobot\":0,\"VoiceGlitch\":0,\"HdRobot\":0,\"HdVoiceGlitch\":0,\"VoiceLayers\":false,\"LayerPitch1\":1.5,\"LayerDelay1\":25,\"LayerPitch2\":-2.5,\"LayerDelay2\":25}"));
            string tunedBare = tunedShown(tunedRead("{\"Size\":240}"));
            string tunedMoved = tunedShown(tunedRead("{\"Volume\":100,\"VoicePitch\":2}"));
            string tunedLouder = tunedShown(tunedRead("{\"Volume\":120}"));
            string tunedKept = tunedShown(tunedRead("{\"VoiceTuned\":true,\"Volume\":100,\"VoicePitch\":0,\"VoiceSpeed\":100}"));
            if (tunedNew != tunedWanted || tunedOld != tunedWanted || tunedBare != tunedWanted || tunedMoved != "100 | 2 | 100 | 0/0 | HD 0/0 | Off | +2, 25 ms | -2.5, 25 ms | True"
                || tunedLouder != "120 | 0 | 100 | 0/0 | HD 0/0 | Off | +2, 25 ms | -2.5, 25 ms | True" || tunedKept != "100 | 0 | 100 | 0/0 | HD 0/0 | Off | +2, 25 ms | -2.5, 25 ms | True" || new Preferences().VoiceTuned)
                throw new Exception("Her tuned voice went wrong: new " + tunedNew + " // untouched " + tunedOld + " // bare " + tunedBare + " // moved " + tunedMoved + " // louder " + tunedLouder + " // kept " + tunedKept);
            checks.Add("PASS her tuned voice: a new install starts at 80% volume, pitch +3, 1.2x, robot and glitch Off on every voice, and voice layers on at +2 and -2.5, 25 ms behind her; settings from before it with every voice slider untouched get it once, and anyone who moved one keeps theirs");

            // Her VOICE LAYERS window from Settings > VOICE: the switch, a slider each, MAIN's pitch and Settings' moving together,
            // Defaults, and the layout at 100%, 150% and 200%.
            int pitchWas = VoiceFx.Pitch;
            string keyOff, opened, flipped, keyOn, slid, mainSlid, fromSettings, defaulted, closedOff, crowded, page, said;
            mainframe.ShowSettings(true);
            try
            {
                keyOff = mainframe.LayersKeyShown;
                mainframe.ShowLayersWindow();
                opened = mainframe.LayersShown;
                int asked = asking;
                mainframe.FlipLayers();
                said = asking > asked ? "switch" : "";
                flipped = mainframe.LayersShown;
                keyOn = mainframe.LayersKeyShown;
                asked = asking;
                mainframe.SlideLayers(1, 30);
                said += asking > asked ? " layer" : "";
                mainframe.SlideLayers(2, 8);
                mainframe.SlideLayers(3, 15);
                mainframe.SlideLayers(4, 18);
                slid = mainframe.LayersShown + " / " + VoiceFx.Layers.Shown + " / " + preferences.LayerPitch1.ToString(System.Globalization.CultureInfo.InvariantCulture) + " " + preferences.LayerDelay1 + " " + preferences.LayerPitch2.ToString(System.Globalization.CultureInfo.InvariantCulture) + " " + preferences.LayerDelay2;
                asked = asking;
                mainframe.SlideLayers(0, 9);
                said += asking > asked ? " main" : "";
                mainSlid = mainframe.LayersShown + " / " + mainframe.VoiceStyleStatus + " / " + VoiceFx.Pitch + " " + preferences.VoicePitch;
                mainframe.SlideVoice(0, 4);
                fromSettings = mainframe.LayersShown;
                page = mainframe.Overlap() ?? mainframe.Outside() ?? mainframe.VoiceHeadingFits();
                snap("mainframe-settings-layers.png");
                crowded = mainframe.LayersCrowded;
                mainframe.LayersDefaults();
                defaulted = mainframe.LayersShown;
                mainframe.FlipLayers();
                closedOff = mainframe.LayersShown + " / " + mainframe.LayersKeyShown + " / " + preferences.VoiceLayers;
                asking++;
                CloseTalk();
            }
            finally
            {
                mainframe.CloseLayers();
                mainframe.ShowSettings(false);
                SetVoicePitch(pitchWas);
                SetVoiceLayers(was);
                mainframe.Sync();
            }
            // Drawn with the layers on at their defaults, as they'd see it after turning them on.
            float machine = mainframe.Px(1000) / 1000f;
            string at100, at150, at200;
            SetVoiceLayers(VoiceFx.Layering.Off.Turned(true));
            try
            {
                at100 = mainframe.LayersAt(1f / machine, Path.Combine(output, "layers-100.png"));
                at150 = mainframe.LayersAt(1.5f / machine, Path.Combine(output, "layers-150.png"));
                at200 = mainframe.LayersAt(2f / machine, Path.Combine(output, "layers-200.png"));
            }
            finally { SetVoiceLayers(was); }
            if (keyOff != "Layers" || opened != "Off | Normal | +2, 25 ms | -2.5, 25 ms" || flipped != "On | Normal | +2, 25 ms | -2.5, 25 ms" || keyOn != "Layers (lit)"
                || slid != "On | Normal | +3, 40 ms | -4.5, 90 ms / On | +3, 40 ms | -4.5, 90 ms / 3 40 -4.5 90" || mainSlid != "On | +3 | +3, 40 ms | -4.5, 90 ms / +3 | Normal | Off | Off / 3 3"
                || fromSettings != "On | -2 | +3, 40 ms | -4.5, 90 ms" || defaulted != "On | -2 | +2, 25 ms | -2.5, 25 ms" || closedOff != "Off | -2 | +2, 25 ms | -2.5, 25 ms / Layers / False" || said != "switch layer main")
                throw new Exception("The VOICE LAYERS window went wrong: " + keyOff + " // " + opened + " // " + flipped + " // " + keyOn + " // " + slid + " // " + mainSlid + " // " + fromSettings + " // " + defaulted + " // " + closedOff + " // she spoke for: " + said);
            if (page != null || crowded != null || at100 != null || at150 != null || at200 != null) throw new Exception("The VOICE LAYERS window's layout doesn't fit: Settings " + page + " / open " + crowded + " / 100% " + at100 + " / 150% " + at150 + " / 200% " + at200);
            checks.Add("PASS VOICE LAYERS window: the Layers button in Settings > VOICE's heading opens it; its switch turns them on and lights the button, each layer's pitch and delay slider sets and saves it, MAIN's pitch and Settings' Pitch move together both ways, Defaults puts both layers back, and the switch and letting go of a slider have her say a line; Settings still fits, with VOICE's note and Layers button fitting their text at 100%, 125%, 150%, 175% and 200% (mainframe-settings-layers.png), and at 100%, 150% and 200% nothing in the window overlaps, pokes out or gets cut off (layers-100.png, layers-150.png, layers-200.png)");
        }

        // Her wake word listens for HeyCapriChanged, so whatever flips the setting starts or stops it.
        internal event Action HeyCapriChanged;

